def _executor_manifest_compact_payload(
    payload: Mapping[str, object] | None,
) -> dict[str, object]:
    """Return status fields that keep proof-body executor blockers visible."""

    if payload is None:
        return {
            "dominant_failure_classification": "",
            "by_proof_body_gate_status": {},
            "n_proof_body_goal_excerpt_rows": 0,
            "first_proof_body_goal_excerpt": [],
        }
    return {
        "dominant_failure_classification": str(
            payload.get("dominant_failure_classification", "") or ""
        ),
        "by_proof_body_gate_status": dict(
            payload.get("by_proof_body_gate_status", {}) or {}
        )
        if isinstance(payload.get("by_proof_body_gate_status", {}), Mapping)
        else {},
        "n_proof_body_goal_excerpt_rows": int(
            payload.get("n_proof_body_goal_excerpt_rows", 0) or 0
        ),
        "first_proof_body_goal_excerpt": [
            str(value)
            for value in payload.get("first_proof_body_goal_excerpt", []) or []
            if str(value).strip()
        ][:8],
    }


def _premise_derivation_bridge_compact_payload(
    payload: Mapping[str, object] | None,
) -> dict[str, object]:
    """Return failure fields that distinguish no evidence candidate from Lean failure."""

    if payload is None:
        return {
            "n_local_lean_skipped_not_evidence_eligible": 0,
            "dominant_failure_classification": "",
            "by_failure_classification": {},
        }
    by_failure = payload.get("by_failure_classification", {}) or {}
    if not isinstance(by_failure, Mapping):
        by_failure = {}
    return {
        "n_local_lean_skipped_not_evidence_eligible": int(
            payload.get("n_local_lean_skipped_not_evidence_eligible", 0) or 0
        ),
        "dominant_failure_classification": str(
            payload.get("dominant_failure_classification", "") or ""
        ),
        "by_failure_classification": dict(by_failure),
    }


def _late_typechecked_candidate_review_unresolved(
    *,
    n_typechecked_candidate_review_packets: int,
    semantic_definition_kernel_verified: bool,
    source_theorem_kernel_verified: bool,
    recheck_queue_ran: bool,
    recheck_queue_n_blocked_packets: int,
    recheck_queue_n_execution_rows: int,
) -> bool:
    """Return whether typechecked semantic-definition candidates still need review."""

    return bool(
        n_typechecked_candidate_review_packets
        and not semantic_definition_kernel_verified
        and not source_theorem_kernel_verified
        and (
            not recheck_queue_ran
            or recheck_queue_n_blocked_packets > 0
            or recheck_queue_n_execution_rows <= 0
        )
    )


def _runtime_manifest_int(payload: Mapping[str, Any], key: str) -> int:
    value = payload.get(key, 0)
    if isinstance(value, (list, tuple, set)):
        return len(value)
    try:
        return int(value or 0)
    except (TypeError, ValueError):
        return 0


def _runtime_manifest_int_sum(payload: Mapping[str, Any], keys: tuple[str, ...]) -> int:
    return sum(_runtime_manifest_int(payload, key) for key in keys)


def _runtime_manifest_first_nonempty(
    payload: Mapping[str, Any],
    keys: tuple[str, ...],
) -> str:
    for key in keys:
        value = str(payload.get(key, "") or "").strip()
        if value:
            return value
    return ""


def _runtime_manifest_first_nonempty_list(
    payload: Mapping[str, Any],
    keys: tuple[str, ...],
) -> list[str]:
    for key in keys:
        value = payload.get(key, []) or []
        if not isinstance(value, (list, tuple)):
            value = [value]
        rows = [str(row) for row in value if str(row).strip()]
        if rows:
            return rows[:8]
    return []


def _runtime_manifest_truth_row(
    evidence_id: str,
    status: str,
    count: int,
    boundary: str,
    *,
    proof_evidence: bool,
    blocker: str = "",
    goal_excerpt: list[str] | None = None,
) -> dict[str, Any]:
    return {
        "evidence_id": evidence_id,
        "status": status,
        "count": int(count),
        "proof_evidence": bool(proof_evidence),
        "blocker": blocker,
        "goal_excerpt": list(goal_excerpt or []),
        "boundary": boundary,
    }


def _runtime_architect_control_truth(payload: Mapping[str, Any]) -> dict[str, Any]:
    n_architect_traces = _runtime_manifest_int(
        payload,
        "n_runtime_architect_coordinator_traces",
    )
    architect_executed = (
        payload.get("architect_coordinator_enabled") is True
        or payload.get("runtime_architect_coordinator_executed") is True
        or n_architect_traces > 0
    )
    architect_context_propagated = (
        payload.get("runtime_research_path_control_propagated") is True
        or payload.get("runtime_architect_coordinator_registered") is True
        or str(payload.get("runtime_stage", "") or "").startswith("architect_")
    )
    if architect_executed:
        return {
            "status": "PRESENT",
            "count": max(1, n_architect_traces),
            "blocker": "",
            "boundary": "Architect control is orchestration evidence, not theorem proof.",
        }
    if architect_context_propagated:
        return {
            "status": "PROPAGATED_FROM_RESUME",
            "count": 0,
            "blocker": (
                "Architect-derived context or runtime stage metadata was present, "
                "but no ArchitectCoordinator trace executed in this runtime budget."
            ),
            "boundary": (
                "Propagated Architect context is continuity evidence only. It is not "
                "live ArchitectCoordinator orchestration evidence and not theorem proof."
            ),
        }
    return {
        "status": "MISSING",
        "count": 0,
        "blocker": "no ArchitectCoordinator trace or propagated Architect context",
        "boundary": "Architect control is orchestration evidence, not theorem proof.",
    }


def _runtime_evidence_truth_table_from_manifest(
    payload: Mapping[str, Any],
) -> dict[str, Any]:
    """Separate runtime progress, support proof, and source-theorem proof."""

    source_kernel_count = _runtime_manifest_int_sum(
        payload,
        (
            "source_theorem_formal_environment_proof_body_executor_n_source_theorem_kernel_verified",
            "source_theorem_exact_proof_body_repair_executor_n_source_theorem_kernel_verified",
            "source_theorem_exact_proof_body_repair_executor_from_proof_body_adapter_feedback_n_source_theorem_kernel_verified",
            "source_theorem_exact_proof_body_repair_executor_from_adapter_premise_derivation_feedback_n_source_theorem_kernel_verified",
            "source_theorem_exact_semantic_definition_typechecked_review_proof_body_recheck_executor_n_source_theorem_kernel_verified",
            "source_theorem_exact_semantic_definition_late_typechecked_review_proof_body_recheck_executor_n_source_theorem_kernel_verified",
            "source_theorem_promotion_post_executor_proofengineer_bridge_n_source_theorem_kernel_verified",
        ),
    )
    proof_body_result_rows = _runtime_manifest_int_sum(
        payload,
        (
            "source_theorem_formal_environment_proof_body_executor_n_result_rows",
            "source_theorem_exact_proof_body_repair_executor_n_result_rows",
            "source_theorem_exact_proof_body_repair_executor_from_proof_body_adapter_feedback_n_result_rows",
            "source_theorem_exact_proof_body_repair_executor_from_adapter_premise_derivation_feedback_n_result_rows",
            "source_theorem_exact_semantic_definition_typechecked_review_proof_body_recheck_executor_n_result_rows",
            "source_theorem_exact_semantic_definition_late_typechecked_review_proof_body_recheck_executor_n_result_rows",
        ),
    )
    proof_body_goal_reached = _runtime_manifest_int(
        payload,
        "source_theorem_formal_environment_proofengineer_n_signature_probes_reached_proof_body",
    )
    proof_body_blocker = _runtime_manifest_first_nonempty(
        payload,
        (
            "source_theorem_exact_proof_body_repair_executor_from_adapter_premise_derivation_feedback_dominant_failure_classification",
            "source_theorem_exact_semantic_definition_typechecked_review_proof_body_recheck_executor_dominant_failure_classification",
            "source_theorem_exact_semantic_definition_late_typechecked_review_proof_body_recheck_executor_dominant_failure_classification",
            "source_theorem_exact_proof_body_repair_executor_from_proof_body_adapter_feedback_dominant_failure_classification",
            "source_theorem_exact_proof_body_repair_executor_dominant_failure_classification",
        ),
    )
    proof_body_goal_excerpt = _runtime_manifest_first_nonempty_list(
        payload,
        (
            "source_theorem_exact_proof_body_repair_executor_from_adapter_premise_derivation_feedback_first_proof_body_goal_excerpt",
            "source_theorem_exact_semantic_definition_typechecked_review_proof_body_recheck_executor_first_proof_body_goal_excerpt",
            "source_theorem_exact_semantic_definition_late_typechecked_review_proof_body_recheck_executor_first_proof_body_goal_excerpt",
            "source_theorem_exact_proof_body_repair_executor_from_proof_body_adapter_feedback_first_proof_body_goal_excerpt",
            "source_theorem_exact_proof_body_repair_executor_first_proof_body_goal_excerpt",
        ),
    )
    bridge_helper_count = _runtime_manifest_int(payload, "n_kernel_verified_subclaims")
    bridge_helper_count += _runtime_manifest_int(
        payload,
        "n_real_kernel_verified_subclaims",
    )
    bridge_helper_count += _runtime_manifest_int(
        payload,
        "memory_kernel_verified_proof_obligation_ids",
    )
    bridge_helper_count += _runtime_manifest_int(
        payload,
        "n_runtime_memory_kernel_verified_proof_obligation_ids",
    )
    theorem_closure_count = _runtime_manifest_int(
        payload,
        "memory_kernel_verified_theorem_reduction_closure_goal_ids",
    )
    theorem_closure_count += _runtime_manifest_int(
        payload,
        "n_runtime_memory_kernel_verified_theorem_reduction_closure_goal_ids",
    )
    source_semantic_count = _runtime_manifest_int(
        payload,
        "memory_kernel_verified_source_theorem_semantic_primitive_ids",
    )
    source_semantic_count += _runtime_manifest_int(
        payload,
        "n_runtime_memory_kernel_verified_source_theorem_semantic_primitive_ids",
    )
    source_semantic_count += _runtime_manifest_int(
        payload,
        "memory_kernel_verified_source_theorem_semantic_support_obligation_ids",
    )
    source_semantic_count += _runtime_manifest_int(
        payload,
        "n_real_kernel_verified_source_theorem_semantic_primitive_subclaims",
    )
    architect_truth = _runtime_architect_control_truth(payload)
    rows = [
        _runtime_manifest_truth_row(
            "live_generator_proposals",
            "PROPOSAL_EVIDENCE"
            if _runtime_manifest_int(payload, "n_live_generator_agents_enabled") > 0
            else "MISSING",
            _runtime_manifest_int(payload, "n_live_generator_agents_enabled"),
            "LLM generator proposals are not theorem proof evidence.",
            proof_evidence=False,
        ),
        _runtime_manifest_truth_row(
            "architect_control",
            str(architect_truth["status"]),
            int(architect_truth["count"]),
            str(architect_truth["boundary"]),
            proof_evidence=False,
            blocker=str(architect_truth["blocker"]),
        ),
        _runtime_manifest_truth_row(
            "environment_algorithm_execution",
            "EXECUTED"
            if _runtime_manifest_int(payload, "n_algorithm_sandbox_executed") > 0
            else "MISSING",
            _runtime_manifest_int(payload, "n_algorithm_sandbox_executed"),
            "Algorithm sandbox execution is engineering evidence, not theorem proof.",
            proof_evidence=False,
        ),
        _runtime_manifest_truth_row(
            "bridge_helper_kernel_evidence",
            "KERNEL_VERIFIED" if bridge_helper_count > 0 else "MISSING",
            bridge_helper_count,
            "Kernel-verified helper/bridge obligations are support evidence only.",
            proof_evidence=bridge_helper_count > 0,
        ),
        _runtime_manifest_truth_row(
            "theorem_reduction_closure_kernel_evidence",
            "KERNEL_VERIFIED" if theorem_closure_count > 0 else "MISSING",
            theorem_closure_count,
            "A theorem-reduction closure is support evidence until the source theorem is checked.",
            proof_evidence=theorem_closure_count > 0,
        ),
        _runtime_manifest_truth_row(
            "source_semantic_primitive_kernel_evidence",
            "KERNEL_VERIFIED" if source_semantic_count > 0 else "MISSING",
            source_semantic_count,
            "Source-semantic primitives are support evidence unless the full source theorem is verified.",
            proof_evidence=source_semantic_count > 0,
        ),
        _runtime_manifest_truth_row(
            "exact_source_proof_body_attempt",
            "SOURCE_KERNEL_VERIFIED"
            if source_kernel_count > 0
            else "PROOF_BODY_REACHED_OPEN"
            if proof_body_goal_reached > 0 or proof_body_result_rows > 0
            else "MISSING",
            proof_body_result_rows or proof_body_goal_reached,
            "Proof-body attempts expose Lean goals/residuals; they are source theorem proof only when source-kernel verified.",
            proof_evidence=source_kernel_count > 0,
            blocker=proof_body_blocker,
            goal_excerpt=proof_body_goal_excerpt,
        ),
        _runtime_manifest_truth_row(
            "full_source_theorem_kernel_evidence",
            "KERNEL_VERIFIED" if source_kernel_count > 0 else "UNPROVED",
            source_kernel_count,
            "Only exact source theorem or reviewed theorem-equivalent local Lean/AXLE verification counts here.",
            proof_evidence=source_kernel_count > 0,
            blocker="" if source_kernel_count > 0 else proof_body_blocker,
            goal_excerpt=[] if source_kernel_count > 0 else proof_body_goal_excerpt,
        ),
        _runtime_manifest_truth_row(
            "formal_gaps",
            "OPEN" if _runtime_manifest_int(payload, "n_formal_gaps") > 0 else "NONE_REPORTED",
            _runtime_manifest_int(payload, "n_formal_gaps"),
            "Formal gaps are explicit blockers, not failures to hide.",
            proof_evidence=False,
        ),
    ]
    return {
        "artifact_kind": "RuntimeEvidenceTruthTable",
        "rows": rows,
        "source_theorem_kernel_verified": source_kernel_count > 0,
        "formal_gaps_open": _runtime_manifest_int(payload, "n_formal_gaps") > 0,
        "current_exact_proof_body_blocker": proof_body_blocker,
        "current_exact_proof_body_goal_excerpt": proof_body_goal_excerpt,
        "boundary": (
            "This runtime manifest truth table separates proposal, execution, support proof, "
            "source-theorem proof, and open formal gaps. It is descriptive runtime evidence; "
            "it does not promote runtime ACCEPTED status or supporting helpers into theorem proof."
        ),
    }


def _runtime_source_theorem_target_names_from_manifest(
    manifest: Mapping[str, Any],
) -> list[str]:
    """Recover intended source-theorem target names from scalar or queue fields."""

    names: list[str] = []

    def add(value: Any) -> None:
        text = str(value or "").strip()
        if text:
            names.append(text)

    for key in (
        "target_theorem_name",
        "source_theorem_target_name",
        "source_theorem_name",
        "target_lean_declaration",
    ):
        add(manifest.get(key, ""))
    for key in (
        "source_theorem_exact_proof_body_repair_target_names",
        "source_theorem_proof_body_adapter_target_names",
        "source_theorem_exact_candidate_repair_target_names",
        "source_theorem_exact_semantic_definition_repair_target_names",
        "memory_source_theorem_exact_candidate_repair_target_names",
    ):
        for value in manifest.get(key, []) or []:
            add(value)
    for row in manifest.get("deterministic_theorem_goals", []) or []:
        if not isinstance(row, Mapping):
            continue
        add(
            row.get("id", "")
            or row.get("target_theorem_name", "")
            or row.get("target_lean_declaration", "")
        )
    for row in manifest.get("formal_targets", []) or []:
        if not isinstance(row, Mapping):
            continue
        add(
            row.get("id", "")
            or row.get("target_theorem_name", "")
            or row.get("target_lean_declaration", "")
        )
    return list(dict.fromkeys(names))


def _runtime_coding_agent_capability_table(payload: Mapping[str, Any]) -> dict[str, Any]:
    """Expose generated-code capability gates directly in runtime manifests."""

    live_generators = _runtime_manifest_int(payload, "n_live_generator_agents_enabled")
    algorithm_executed = _runtime_manifest_int(
        payload,
        "n_generated_code_sandbox_executed",
    )
    algorithm_repair_sequences = _runtime_manifest_int(
        payload,
        "n_generated_code_sandbox_failed_then_passed_repair_sequences",
    )
    simulation_executed = _runtime_manifest_int(
        payload,
        "n_generated_simulation_sandbox_executed",
    )
    simulation_repair_sequences = _runtime_manifest_int(
        payload,
        "n_generated_simulation_sandbox_failed_then_passed_repair_sequences",
    )
    formalizer_checked = _runtime_manifest_int(
        payload,
        "n_formalizer_lean_candidate_local_lean_checked",
    )
    formalizer_live_proof_state_requests = _runtime_manifest_int(
        payload,
        "n_formalizer_lean_candidate_live_proof_state_requests",
    )
    formalizer_lean_lsp_mcp_ready_requests = _runtime_manifest_int(
        payload,
        "n_formalizer_lean_candidate_lean_lsp_mcp_ready_requests",
    )
    formalizer_proof_state_feedback_rows = _runtime_manifest_int(
        payload,
        "n_formalizer_lean_candidate_proof_state_feedback_rows",
    )
    formalizer_local_lean_tool_calls = _runtime_manifest_int(
        payload,
        "n_formalizer_lean_candidate_local_lean_tool_calls",
    )
    formalizer_lean_lsp_mcp_live_calls = _runtime_manifest_int(
        payload,
        "n_formalizer_lean_candidate_lean_lsp_mcp_live_calls",
    )
    formalizer_repair_sequences = _runtime_manifest_int(
        payload,
        "n_formalizer_lean_candidate_failed_then_passed_repair_sequences",
    )
    llm_formalizer_proposals = _runtime_manifest_int(
        payload,
        "n_llm_formalizer_proof_engineer_proposals",
    )
    deterministic_formalizer_seeds = _runtime_manifest_int(
        payload,
        "n_deterministic_formalizer_work_order_seed_proposals",
    )
    attached_coding_live_gate = (
        bool(
            payload.get(
                "internal_coding_agent_generated_code_repair_eval_capability_evidence_ok",
                False,
            )
        )
        and bool(
            payload.get(
                "internal_coding_agent_generated_code_repair_eval_live_generator",
                False,
            )
        )
        and not bool(
            payload.get(
                "internal_coding_agent_generated_code_repair_eval_static_or_fixture_only",
                False,
            )
        )
    )
    attached_algorithm_repair_sequences = _runtime_manifest_int(
        payload,
        "internal_coding_agent_generated_code_repair_eval_algorithm_repair_sequences",
    )
    attached_simulation_repair_sequences = _runtime_manifest_int(
        payload,
        "internal_coding_agent_generated_code_repair_eval_simulation_repair_sequences",
    )
    attached_formalizer_live_gate = (
        bool(
            payload.get(
                "internal_formalizer_lean_candidate_repair_eval_capability_evidence_ok",
                False,
            )
        )
        and bool(
            payload.get(
                "internal_formalizer_lean_candidate_repair_eval_live_generator",
                False,
            )
        )
        and not bool(
            payload.get(
                "internal_formalizer_lean_candidate_repair_eval_static_or_fixture_only",
                False,
            )
        )
    )
    attached_formalizer_checked = _runtime_manifest_int(
        payload,
        "internal_formalizer_lean_candidate_repair_eval_local_lean_checked",
    )
    attached_formalizer_repair_sequences = _runtime_manifest_int(
        payload,
        "internal_formalizer_lean_candidate_repair_eval_repair_sequences",
    )
    rows = [
        {
            "capability_id": "live_generator_agents_enabled",
            "passed": live_generators > 0,
            "count": live_generators,
            "evidence": f"n_live_generator_agents_enabled={live_generators}",
            "blocker": (
                ""
                if live_generators > 0
                else "static/replay providers cannot demonstrate coding-agent capability"
            ),
        },
        {
            "capability_id": "generated_algorithm_code_executed_locally",
            "passed": algorithm_executed > 0
            or (attached_coding_live_gate and attached_algorithm_repair_sequences > 0),
            "count": algorithm_executed or attached_algorithm_repair_sequences,
            "evidence": (
                f"n_generated_code_sandbox_executed={algorithm_executed}; "
                "attached_live_algorithm_repair_sequences="
                f"{attached_algorithm_repair_sequences}"
            ),
            "blocker": (
                ""
                if algorithm_executed > 0
                or (attached_coding_live_gate and attached_algorithm_repair_sequences > 0)
                else "no Claude/OpenAI-generated algorithm code executed locally"
            ),
        },
        {
            "capability_id": "generated_algorithm_repair_loop_observed",
            "passed": algorithm_repair_sequences > 0
            or (attached_coding_live_gate and attached_algorithm_repair_sequences > 0),
            "count": algorithm_repair_sequences
            or attached_algorithm_repair_sequences,
            "evidence": (
                "n_generated_code_sandbox_failed_then_passed_repair_sequences="
                f"{algorithm_repair_sequences}; "
                "attached_live_algorithm_repair_sequences="
                f"{attached_algorithm_repair_sequences}"
            ),
            "blocker": (
                ""
                if algorithm_repair_sequences > 0
                or (attached_coding_live_gate and attached_algorithm_repair_sequences > 0)
                else "one-shot generated algorithm execution is not evidence of autonomous code repair"
            ),
        },
        {
            "capability_id": "generated_simulation_code_executed_locally",
            "passed": simulation_executed > 0
            or (attached_coding_live_gate and attached_simulation_repair_sequences > 0),
            "count": simulation_executed or attached_simulation_repair_sequences,
            "evidence": (
                "n_generated_simulation_sandbox_executed="
                f"{simulation_executed}; "
                "attached_live_simulation_repair_sequences="
                f"{attached_simulation_repair_sequences}"
            ),
            "blocker": (
                ""
                if simulation_executed > 0
                or (attached_coding_live_gate and attached_simulation_repair_sequences > 0)
                else "no Claude/OpenAI-generated simulation code executed locally"
            ),
        },
        {
            "capability_id": "generated_simulation_repair_loop_observed",
            "passed": simulation_repair_sequences > 0
            or (attached_coding_live_gate and attached_simulation_repair_sequences > 0),
            "count": simulation_repair_sequences
            or attached_simulation_repair_sequences,
            "evidence": (
                "n_generated_simulation_sandbox_failed_then_passed_repair_sequences="
                f"{simulation_repair_sequences}; "
                "attached_live_simulation_repair_sequences="
                f"{attached_simulation_repair_sequences}"
            ),
            "blocker": (
                ""
                if simulation_repair_sequences > 0
                or (attached_coding_live_gate and attached_simulation_repair_sequences > 0)
                else "one-shot generated simulation execution is not evidence of autonomous simulation repair"
            ),
        },
        {
            "capability_id": "llm_formalizer_proofengineer_proposal_observed",
            "passed": llm_formalizer_proposals > 0 or attached_formalizer_live_gate,
            "count": llm_formalizer_proposals
            or (1 if attached_formalizer_live_gate else 0),
            "evidence": (
                "n_llm_formalizer_proof_engineer_proposals="
                f"{llm_formalizer_proposals}; "
                "n_deterministic_formalizer_work_order_seed_proposals="
                f"{deterministic_formalizer_seeds}; "
                "attached_live_formalizer_repair_eval="
                f"{attached_formalizer_live_gate}"
            ),
            "blocker": (
                ""
                if llm_formalizer_proposals > 0 or attached_formalizer_live_gate
                else (
                    "deterministic theorem-closure seeds are work-order "
                    "scaffolds; they do not demonstrate live Formalizer or "
                    "ProofEngineer capability"
                )
            ),
        },
        {
            "capability_id": "formalizer_lean_candidate_checked_locally",
            "passed": llm_formalizer_proposals > 0
            and formalizer_checked > 0
            or (attached_formalizer_live_gate and attached_formalizer_checked > 0),
            "count": formalizer_checked or attached_formalizer_checked,
            "evidence": (
                "n_llm_formalizer_proof_engineer_proposals="
                f"{llm_formalizer_proposals}; "
                "n_formalizer_lean_candidate_local_lean_checked="
                f"{formalizer_checked}; "
                "attached_live_local_lean_checked="
                f"{attached_formalizer_checked}"
            ),
            "blocker": (
                ""
                if llm_formalizer_proposals > 0
                and formalizer_checked > 0
                or (attached_formalizer_live_gate and attached_formalizer_checked > 0)
                else (
                    "no Claude/OpenAI-generated Lean candidate was checked "
                    "locally; deterministic work-order seeds and proof-bank "
                    "queues do not count as Formalizer capability"
                )
            ),
        },
        {
            "capability_id": "formalizer_lean_candidate_proof_state_request_routed",
            "passed": formalizer_live_proof_state_requests > 0
            and formalizer_lean_lsp_mcp_ready_requests > 0,
            "count": formalizer_live_proof_state_requests,
            "evidence": (
                "n_formalizer_lean_candidate_live_proof_state_requests="
                f"{formalizer_live_proof_state_requests}; "
                "n_formalizer_lean_candidate_lean_lsp_mcp_ready_requests="
                f"{formalizer_lean_lsp_mcp_ready_requests}"
            ),
            "blocker": (
                ""
                if formalizer_live_proof_state_requests > 0
                and formalizer_lean_lsp_mcp_ready_requests > 0
                else (
                    "Formalizer Lean failures were not routed into a Lean "
                    "LSP/MCP-ready ProofEngineer proof-state request"
                )
            ),
        },
        {
            "capability_id": "formalizer_lean_candidate_proof_state_feedback_recorded",
            "passed": formalizer_proof_state_feedback_rows > 0,
            "count": formalizer_proof_state_feedback_rows,
            "evidence": (
                "n_formalizer_lean_candidate_proof_state_feedback_rows="
                f"{formalizer_proof_state_feedback_rows}"
            ),
            "blocker": (
                ""
                if formalizer_proof_state_feedback_rows > 0
                else (
                    "failed generated Lean candidates did not produce structured "
                    "ProofEngineer feedback carrying diagnostics/residual goals "
                    "back to the LLM repair loop"
                )
            ),
        },
        {
            "capability_id": "formalizer_local_lean_tool_call_observed",
            "passed": formalizer_local_lean_tool_calls > 0,
            "count": formalizer_local_lean_tool_calls,
            "evidence": (
                "n_formalizer_lean_candidate_local_lean_tool_calls="
                f"{formalizer_local_lean_tool_calls}"
            ),
            "blocker": (
                ""
                if formalizer_local_lean_tool_calls > 0
                else (
                    "ProofEngineer feedback did not record an actual local Lean "
                    "tool invocation; local candidate checks without tool-call "
                    "trace are weaker diagnostics"
                )
            ),
        },
        {
            "capability_id": "formalizer_live_prover_tool_call_observed",
            "passed": formalizer_lean_lsp_mcp_live_calls > 0,
            "count": formalizer_lean_lsp_mcp_live_calls,
            "evidence": (
                "n_formalizer_lean_candidate_lean_lsp_mcp_live_calls="
                f"{formalizer_lean_lsp_mcp_live_calls}"
            ),
            "blocker": (
                ""
                if formalizer_lean_lsp_mcp_live_calls > 0
                else (
                    "LeanDojo/ReProver/Lean-LSP style tools are only requested "
                    "or emulated by local Lean feedback; no live prover tool "
                    "call was observed in this runtime"
                )
            ),
        },
        {
            "capability_id": "formalizer_lean_candidate_repair_loop_observed",
            "passed": formalizer_repair_sequences > 0
            or (
                attached_formalizer_live_gate
                and attached_formalizer_repair_sequences > 0
            ),
            "count": formalizer_repair_sequences
            or attached_formalizer_repair_sequences,
            "evidence": (
                "n_formalizer_lean_candidate_failed_then_passed_repair_sequences="
                f"{formalizer_repair_sequences}; "
                "attached_live_formalizer_repair_sequences="
                f"{attached_formalizer_repair_sequences}"
            ),
            "blocker": (
                ""
                if formalizer_repair_sequences > 0
                or (
                    attached_formalizer_live_gate
                    and attached_formalizer_repair_sequences > 0
                )
                else "no generated Lean candidate failure was followed by a local-kernel-checked repair"
            ),
        },
    ]
    return {
        "artifact_kind": "RuntimeCodingAgentCapabilityTable",
        "rows": rows,
        "coding_agent_capability_ready": all(row["passed"] for row in rows),
        "algorithm_repair_loop_observed": algorithm_repair_sequences > 0
        or (attached_coding_live_gate and attached_algorithm_repair_sequences > 0),
        "simulation_repair_loop_observed": simulation_repair_sequences > 0
        or (attached_coding_live_gate and attached_simulation_repair_sequences > 0),
        "formalizer_lean_repair_loop_observed": formalizer_repair_sequences > 0
        or (
            attached_formalizer_live_gate
            and attached_formalizer_repair_sequences > 0
        ),
        "boundary": (
            "This table is capability evidence for the generated-code environment "
            "loop only. It does not make simulations proof evidence and does not "
            "prove any theorem. Static/replay providers and one-shot generated-code "
            "execution are not sufficient."
        ),
    }


def _runtime_coding_agent_capability_learning_rows(
    *,
    manifest: Mapping[str, Any],
    capability_table: Mapping[str, Any],
) -> list[dict[str, Any]]:
    """Turn missing generated-code repair evidence into next-run memory."""

    rows = [
        row
        for row in capability_table.get("rows", []) or []
        if isinstance(row, Mapping) and not bool(row.get("passed", False))
    ]
    if not rows:
        return []
    question_ids = [
        str(value)
        for value in manifest.get("question_ids", []) or []
        if str(value).strip()
    ]
    question_id = question_ids[0] if question_ids else ""
    generated_rows: list[dict[str, Any]] = []
    for row in rows:
        capability_id = str(row.get("capability_id", "") or "").strip()
        if not capability_id:
            continue
        if capability_id == "generated_algorithm_repair_loop_observed":
            next_owner = "AlgorithmEngineer"
            target_behavior = (
                "Run a Claude/OpenAI-generated algorithm-code fail-then-pass "
                "repair loop: generated Python executes locally, exposes the "
                "failure output, revises from that feedback, and passes sandbox "
                "and metric gates."
            )
            recommended_eval = (
                "python3 -m ai_statistician.cli coding-agent-generated-code-repair-eval "
                "--provider anthropic --question-id conformal_prediction_coverage"
            )
            success_metric = (
                "algorithm_repair_sequences>0 and "
                "algorithm_capability_evidence_ok=true in the combined "
                "coding-agent generated-code repair eval manifest"
            )
        elif capability_id == "generated_simulation_repair_loop_observed":
            next_owner = "SimulationEvaluator"
            target_behavior = (
                "Run a Claude/OpenAI-generated simulation-code fail-then-pass "
                "repair loop: generated stress-test code executes locally, "
                "exposes the failure output, revises from that feedback, and "
                "passes sandbox and metric gates."
            )
            recommended_eval = (
                "python3 -m ai_statistician.cli coding-agent-generated-code-repair-eval "
                "--provider anthropic --question-id conformal_prediction_coverage"
            )
            success_metric = (
                "simulation_repair_sequences>0 and "
                "simulation_capability_evidence_ok=true in the combined "
                "coding-agent generated-code repair eval manifest"
            )
        elif capability_id == "generated_algorithm_code_executed_locally":
            next_owner = "AlgorithmEngineer"
            target_behavior = (
                "Produce and locally execute generated algorithm code instead "
                "of relying on registered templates or static replay."
            )
            recommended_eval = (
                "python3 -m ai_statistician.cli algorithm-engineer-generated-code-repair-eval "
                "--provider anthropic --question-id conformal_prediction_coverage"
            )
            success_metric = (
                "n_generated_code_sandbox_executed>0 from a live provider with "
                "static_or_fixture_only=false"
            )
        elif capability_id == "generated_simulation_code_executed_locally":
            next_owner = "SimulationEvaluator"
            target_behavior = (
                "Produce and locally execute generated simulation code instead "
                "of relying on registered simulators or static replay."
            )
            recommended_eval = (
                "python3 -m ai_statistician.cli simulation-engineer-generated-code-repair-eval "
                "--provider anthropic --question-id conformal_prediction_coverage"
            )
            success_metric = (
                "n_generated_simulation_sandbox_executed>0 from a live provider "
                "with static_or_fixture_only=false"
            )
        elif capability_id == "llm_formalizer_proofengineer_proposal_observed":
            next_owner = "FormalizationEvaluator"
            target_behavior = (
                "Use a live Claude/OpenAI Formalizer/ProofEngineer proposal for "
                "formalization capability evaluation. Deterministic theorem-"
                "closure seeds may create work orders, but they must not replace "
                "the LLM agent in capability claims."
            )
            recommended_eval = (
                "python3 -m ai_statistician.cli research-agent-runtime "
                "--provider anthropic --formalizer-candidate-local-lean "
                "--local-lean"
            )
            success_metric = (
                "n_llm_formalizer_proof_engineer_proposals>0; "
                "n_deterministic_formalizer_work_order_seed_proposals alone is "
                "not agentic capability"
            )
        elif capability_id == "formalizer_lean_candidate_checked_locally":
            next_owner = "FormalizationEvaluator"
            target_behavior = (
                "Produce a Claude/OpenAI-generated Lean candidate and check it "
                "with local Lean/AXLE diagnostics instead of relying only on "
                "proof packets, proof-bank queues, or static fixtures."
            )
            recommended_eval = (
                "python3 -m ai_statistician.cli formalizer-lean-candidate-repair-eval "
                "--provider anthropic --question-id conformal_prediction_coverage"
            )
            success_metric = (
                "n_formalizer_lean_candidate_local_lean_checked>0 from a live "
                "provider with static_or_fixture_only=false"
            )
        elif capability_id == "formalizer_lean_candidate_proof_state_request_routed":
            next_owner = "ProofEngineer"
            target_behavior = (
                "Route each failed Claude/OpenAI-generated Lean candidate into "
                "a ProofEngineer proof-state request carrying the artifact path, "
                "target declaration location, Lean diagnostics, and requested "
                "Lean LSP/MCP tools such as lean_goal, lean_state_search, and "
                "lean_multi_attempt."
            )
            recommended_eval = (
                "python3 -m ai_statistician.cli research-agent-runtime "
                "--provider anthropic --formalizer-candidate-local-lean "
                "--local-lean"
            )
            success_metric = (
                "n_formalizer_lean_candidate_live_proof_state_requests>0 and "
                "n_formalizer_lean_candidate_lean_lsp_mcp_ready_requests>0"
            )
        elif capability_id == "formalizer_lean_candidate_proof_state_feedback_recorded":
            next_owner = "ProofEngineer"
            target_behavior = (
                "Convert failed Claude/OpenAI-generated Lean candidate checks into "
                "structured ProofEngineer feedback rows that carry Lean diagnostics, "
                "residual goals, requested prover tools, and exact artifact identity "
                "back into the next Formalizer/ProofEngineer prompt."
            )
            recommended_eval = (
                "python3 -m ai_statistician.cli research-agent-runtime "
                "--provider anthropic --formalizer-candidate-local-lean "
                "--local-lean"
            )
            success_metric = (
                "n_formalizer_lean_candidate_proof_state_feedback_rows>0 with "
                "diagnostics/residual_goals/requested_tools preserved in runtime "
                "learning rows"
            )
        elif capability_id == "formalizer_local_lean_tool_call_observed":
            next_owner = "ProofEngineer"
            target_behavior = (
                "Record the actual local Lean verifier call as a ProofEngineer "
                "tool observation, including executed_tools/tool_call_trace, so "
                "Claude can repair from real verifier output instead of a generic "
                "failed-check flag."
            )
            recommended_eval = (
                "python3 -m ai_statistician.cli research-agent-runtime "
                "--provider anthropic --formalizer-candidate-local-lean "
                "--local-lean"
            )
            success_metric = (
                "n_formalizer_lean_candidate_local_lean_tool_calls>0 with "
                "executed_tools/tool_call_trace preserved in runtime learning rows"
            )
        elif capability_id == "formalizer_live_prover_tool_call_observed":
            next_owner = "ProofEngineer"
            target_behavior = (
                "Use a live prover tool adapter, not just a queued request: inspect "
                "the exact candidate with Lean LSP/LeanDojo/ReProver-style search "
                "or an explicitly recorded equivalent tool call, then rerun local "
                "Lean/AXLE on the repaired artifact."
            )
            recommended_eval = (
                "python3 -m ai_statistician.cli research-agent-runtime "
                "--provider anthropic --formalizer-candidate-local-lean "
                "--local-lean"
            )
            success_metric = (
                "n_formalizer_lean_candidate_lean_lsp_mcp_live_calls>0; "
                "ready/request rows alone do not satisfy this capability"
            )
        elif capability_id == "formalizer_lean_candidate_repair_loop_observed":
            next_owner = "FormalizationEvaluator"
            target_behavior = (
                "Run a Claude/OpenAI-generated Lean-candidate fail-then-pass "
                "repair loop: local Lean exposes the initial failure, the "
                "Formalizer revises from diagnostics, and the repaired helper "
                "candidate compiles locally."
            )
            recommended_eval = (
                "python3 -m ai_statistician.cli formalizer-lean-candidate-repair-eval "
                "--provider anthropic --question-id conformal_prediction_coverage"
            )
            success_metric = (
                "n_formalizer_lean_candidate_failed_then_passed_repair_sequences>0 "
                "and capability_evidence_ok=true in the Formalizer Lean-candidate "
                "repair eval manifest"
            )
        else:
            next_owner = "ArchitectCoordinator"
            target_behavior = (
                "Use live Anthropic/OpenAI generator agents; static/replay "
                "fixtures can only test plumbing and must not count as "
                "agentic capability."
            )
            recommended_eval = (
                "python3 -m ai_statistician.cli coding-agent-generated-code-repair-eval "
                "--provider anthropic --question-id conformal_prediction_coverage"
            )
            success_metric = (
                "live_generator=true and capability_evidence_ok=true in the "
                "combined coding-agent generated-code repair eval manifest"
            )
        generated_rows.append(
            {
                "schema_version": RUNTIME_SCHEMA_VERSION,
                "artifact_kind": "RuntimeLearningRow",
                "created_at": datetime.now(timezone.utc).isoformat(),
                "question_id": question_id,
                "learning_task": "coding_agent_generated_code_capability_feedback",
                "capability_id": capability_id,
                "next_owner_subsystem": next_owner,
                "target_behavior": target_behavior,
                "recommended_capability_eval_command": recommended_eval,
                "success_metric": success_metric,
                "input_summary": {
                    "trigger": "RUNTIME_CODING_AGENT_CAPABILITY_TABLE",
                    "capability_id": capability_id,
                    "count": int(row.get("count", 0) or 0),
                    "evidence": str(row.get("evidence", "") or ""),
                    "blocker": str(row.get("blocker", "") or ""),
                    "coding_agent_capability_ready": bool(
                        capability_table.get("coding_agent_capability_ready", False)
                    ),
                },
                "proof_evidence_status": (
                    "CODING_AGENT_CAPABILITY_FEEDBACK_NOT_PROOF_EVIDENCE"
                ),
                "boundary": (
                    "This row is routing memory for generated-code environment-loop "
                    "capability. It is not theorem proof evidence, not simulation "
                    "proof, and not evidence that a static fixture can do research."
                ),
            }
        )
    return generated_rows


def _runtime_evidence_truth_learning_rows(
    *,
    manifest: Mapping[str, Any],
    truth_table: Mapping[str, Any],
) -> list[dict[str, Any]]:
    """Export source-theorem proof status as prompt memory for the next run."""

    rows_by_id = {
        str(row.get("evidence_id", "") or ""): row
        for row in truth_table.get("rows", []) or []
        if isinstance(row, Mapping)
    }
    full_source_row = rows_by_id.get("full_source_theorem_kernel_evidence", {})
    exact_attempt_row = rows_by_id.get("exact_source_proof_body_attempt", {})
    formal_gap_row = rows_by_id.get("formal_gaps", {})
    source_verified = bool(truth_table.get("source_theorem_kernel_verified", False))
    formal_gaps_open = bool(truth_table.get("formal_gaps_open", False))
    proof_body_status = str(exact_attempt_row.get("status", "") or "")
    if source_verified and not formal_gaps_open:
        return []
    if (
        proof_body_status == "MISSING"
        and not formal_gaps_open
        and str(full_source_row.get("status", "") or "") != "UNPROVED"
    ):
        return []
    question_ids = [
        str(value)
        for value in manifest.get("question_ids", []) or []
        if str(value).strip()
    ]
    question_id = question_ids[0] if question_ids else ""
    goal_excerpt = [
        str(value)
        for value in truth_table.get("current_exact_proof_body_goal_excerpt", []) or []
        if str(value).strip()
    ][:4]
    blocker = str(truth_table.get("current_exact_proof_body_blocker", "") or "")
    proof_body_goal_reached = proof_body_status in {
        "PROOF_BODY_REACHED_OPEN",
        "SOURCE_KERNEL_VERIFIED",
    }
    semantic_review_blocked = blocker in _SOURCE_THEOREM_EXACT_SEMANTIC_REPAIR_FAILURES
    source_theorem_ready_for_exact_proof_body = bool(
        proof_body_goal_reached and not semantic_review_blocked
    )
    target_theorem_names = _runtime_source_theorem_target_names_from_manifest(
        manifest
    )
    target_theorem_name = target_theorem_names[0] if target_theorem_names else ""
    premise_gap_kind = (
        blocker
        if (
            "adapter_context" in blocker
            or "premise" in blocker
            or "bridge" in blocker
        )
        else ""
    )
    premise_name = ""
    premise_target_type = goal_excerpt[0] if goal_excerpt else ""
    if (
        goal_excerpt
        and ":" in goal_excerpt[0]
        and not goal_excerpt[0].lstrip().startswith("⊢")
    ):
        premise_name, premise_target_type = [
            value.strip() for value in goal_excerpt[0].split(":", 1)
        ]
    if semantic_review_blocked:
        target_behavior = (
            "review exact source-theorem semantic definitions before resuming "
            "proof-body search; do not treat a semantic-review blocker as proof-body "
            "readiness"
        )
    elif proof_body_status == "PROOF_BODY_REACHED_OPEN":
        target_behavior = (
            "route to ProofEngineer/LeanProver for exact source proof-body repair; "
            "if the blocker is missing bridge premises, route the premise derivation "
            "upstream to TheoryDeveloper/Formalizer before retrying the exact source theorem"
        )
    elif formal_gaps_open:
        target_behavior = (
            "route open formal gaps to Formalizer/ProofEngineer before treating the "
            "runtime result as accepted theorem progress"
        )
    else:
        target_behavior = (
            "keep the exact source theorem marked unproved until local Lean/AXLE "
            "reports source theorem kernel verification"
        )
    return [
        {
            "schema_version": RUNTIME_SCHEMA_VERSION,
            "artifact_kind": "RuntimeLearningRow",
            "learning_task": "source_theorem_truth_table_feedback",
            "question_id": question_id,
            "work_order_id": stable_hash(
                {
                    "learning_task": "source_theorem_truth_table_feedback",
                    "question_id": question_id,
                    "target_theorem_names": target_theorem_names,
                    "proof_body_status": proof_body_status,
                    "blocker": blocker,
                }
            )[:16],
            "target_theorem_name": target_theorem_name,
            "target_ids": target_theorem_names,
            "target_theorem_goal_ids": target_theorem_names,
            "premise_name": premise_name,
            "premise_derivation_gap_kind": premise_gap_kind,
            "premise_target_type": premise_target_type,
            "recommended_next_action": target_behavior,
            "input_summary": {
                "trigger": "RUNTIME_EVIDENCE_TRUTH_TABLE",
                "target_theorem_name": target_theorem_name,
                "target_ids": target_theorem_names,
                "target_theorem_goal_ids": target_theorem_names,
                "source_theorem_kernel_verified": source_verified,
                "source_theorem_ready_for_exact_proof_body": (
                    source_theorem_ready_for_exact_proof_body
                ),
                "proof_body_goal_reached": proof_body_goal_reached,
                "proof_body_semantic_review_blocked": semantic_review_blocked,
                "failure_classification": blocker,
                "premise_name": premise_name,
                "premise_derivation_gap_kind": premise_gap_kind,
                "premise_target_type": premise_target_type,
                "proof_body_goal_excerpt": goal_excerpt,
                "formalization_counts": {
                    "formal_gaps": int(formal_gap_row.get("count", 0) or 0),
                    "source_theorem_kernel_verified": int(
                        full_source_row.get("count", 0) or 0
                    ),
                },
            },
            "target_behavior": target_behavior,
            "acceptance_gate": (
                "Only local Lean/AXLE source theorem kernel verification can clear "
                "full_source_theorem_kernel_evidence; runtime ACCEPTED, helper proofs, "
                "closure proofs, and simulation do not clear this gate."
            ),
            "proof_evidence_status": "RUNTIME_TRUTH_TABLE_FEEDBACK_NOT_PROOF_EVIDENCE",
        }
    ]


def _runtime_research_acceptance_contract_from_manifest(
    manifest: Mapping[str, Any],
    *,
    formal_verification_policy: str,
    recommended_research_path: str = "",
) -> dict[str, Any]:
    policy = _normalized_formal_verification_policy(formal_verification_policy)
    research_path = _normalized_recommended_research_path(
        recommended_research_path,
        formal_verification_policy=policy,
    )
    truth_table = manifest.get("runtime_evidence_truth_table", {})
    if not isinstance(truth_table, Mapping):
        truth_table = {}
    completion_summary = manifest.get("runtime_completion_summary", {})
    if not isinstance(completion_summary, Mapping):
        completion_summary = {}
    source_verified = bool(truth_table.get("source_theorem_kernel_verified", False))
    formal_gaps_open = bool(truth_table.get("formal_gaps_open", False))
    kernel_subclaims = _runtime_manifest_int(manifest, "n_kernel_verified_subclaims")
    accepted = int(completion_summary.get("accepted", 0) or 0) > 0
    if source_verified and not formal_gaps_open:
        verified_level = "full"
    elif source_verified or kernel_subclaims > 0:
        verified_level = "partial"
    else:
        verified_level = "none"
    formal_required = policy == "required"
    if policy == "required":
        if verified_level == "full":
            status = "FULL_THEOREM_KERNEL_VERIFIED"
            can_report = True
        elif accepted:
            status = "FORMAL_REQUIRED_BLOCKED_AFTER_RUNTIME_ACCEPTED"
            can_report = False
        else:
            status = "FORMAL_REQUIRED_IN_PROGRESS"
            can_report = False
    elif policy == "optional":
        if verified_level == "full":
            status = "FULL_THEOREM_KERNEL_VERIFIED"
        elif verified_level == "partial" and accepted:
            status = "RESEARCH_CANDIDATE_ACCEPTED_WITH_PARTIAL_FORMAL_EVIDENCE"
        elif accepted:
            status = "RESEARCH_CANDIDATE_ACCEPTED_WITH_FORMAL_GAPS_DISCLOSED"
        else:
            status = "RESEARCH_IN_PROGRESS_FORMAL_OPTIONAL"
        can_report = accepted or verified_level in {"partial", "full"}
    else:
        if accepted:
            status = "RESEARCH_CANDIDATE_ACCEPTED_FORMAL_ADVISORY"
        elif verified_level == "full":
            status = "FULL_THEOREM_KERNEL_VERIFIED"
        elif verified_level == "partial":
            status = "RESEARCH_IN_PROGRESS_WITH_ADVISORY_FORMAL_EVIDENCE"
        else:
            status = "RESEARCH_IN_PROGRESS_FORMAL_ADVISORY"
        can_report = accepted or verified_level in {"partial", "full"}
    return {
        "schema_version": RUNTIME_SCHEMA_VERSION,
        "artifact_kind": "RuntimeResearchAcceptanceContract",
        "formal_verification_policy": policy,
        "formal_required_for_final": formal_required,
        "recommended_research_path": research_path,
        "research_acceptance_status": status,
        "can_report_research_candidate": can_report,
        "formally_verified_level": verified_level,
        "source_theorem_kernel_verified": source_verified,
        "formal_gaps_open": formal_gaps_open,
        "n_kernel_verified_subclaims": kernel_subclaims,
        "runtime_accepted": accepted,
        "must_disclose_formal_gaps": True,
        "acceptance_modes": [
            "full source theorem kernel proof required"
            if policy == "required"
            else "simulation, implementation, derivation, and critic review may support a research candidate"
            if policy == "advisory"
            else "Architect may choose simulation-first, proof-first, or dual-track evidence"
        ],
        "proof_evidence_boundary": (
            "This contract governs research-candidate acceptance semantics. It "
            "does not convert LLM proposals, simulation evidence, typechecking, "
            "or runtime ACCEPTED status into theorem proof."
        ),
    }


