    def append_same_run_exact_semantic_work_orders_from_learning_rows(
        bridge_learning_rows: list[dict[str, Any]],
        *,
        queue_name: str,
    ) -> None:
        if not bridge_learning_rows:
            return
        candidate_rows = (
            _runtime_source_theorem_exact_semantic_definition_work_order_rows_from_learning_rows(
                bridge_learning_rows
            )
        )
        candidate_rows.extend(
            _runtime_source_theorem_exact_semantic_definition_work_order_rows_from_semantic_alignment_learning_rows(
                bridge_learning_rows
            )
        )
        if not candidate_rows:
            return
        before_keys = set(seen_exact_semantic_work_order_by_key)
        new_rows: list[dict[str, Any]] = []
        late_lookup_rows: list[dict[str, Any]] = []
        for candidate in candidate_rows:
            key = (
                str(candidate.get("target_theorem_name", "") or ""),
                str(candidate.get("placeholder_symbol", "") or ""),
                tuple(candidate.get("candidate_registered_obligation_ids", []) or []),
            )
            append_or_merge_exact_semantic_work_order(candidate)
            merged = seen_exact_semantic_work_order_by_key.get(key)
            merged_row = dict(merged) if isinstance(merged, Mapping) else candidate
            if key not in before_keys:
                new_rows.append(merged_row)
                late_lookup_rows.append(merged_row)
                before_keys.add(key)
            elif (
                str(candidate.get("premise_name", "") or "").strip()
                or str(candidate.get("premise_target_type", "") or "").strip()
                or str(candidate.get("semantic_primitive_gap_kind", "") or "").strip()
                == "source_to_bridge_premise_semantic_gap"
            ):
                late_lookup_rows.append(merged_row)
        if not new_rows and not late_lookup_rows:
            return
        safe_queue_name = _safe_identifier(queue_name)[:96]
        late_queue_path = (
            out_dir
            / (
                "runtime_source_theorem_exact_semantic_definition_work_orders_"
                f"from_{safe_queue_name}.jsonl"
            )
        )
        _write_jsonl(late_queue_path, late_lookup_rows)
        same_run_exact_semantic_definition_new_rows_by_queue[queue_name] = list(
            new_rows
        )
        same_run_exact_semantic_definition_lookup_rows_by_queue[queue_name] = list(
            late_lookup_rows
        )
        same_run_exact_semantic_definition_queue_paths_by_queue[queue_name] = str(
            late_queue_path
        )
        _write_jsonl(
            source_theorem_exact_semantic_definition_work_orders_path,
            source_theorem_exact_semantic_definition_work_order_rows,
        )
        if new_rows:
            learning_rows.extend(
                _runtime_source_theorem_exact_semantic_definition_learning_rows(
                    new_rows
                )
            )
            next_action_rows = _append_runtime_generated_next_action_rows(
                agenda_rows,
                new_rows,
                queue_name=queue_name,
            )
            if next_action_rows:
                generated_next_action_rows.extend(next_action_rows)
                learning_rows.extend(
                    _runtime_generated_next_action_learning_rows(next_action_rows)
                )
                _write_jsonl(agenda_path, agenda_rows)
