def _critic_source_theorem_exact_semantic_definition_repair_feedback(
    formalization_manifest: Mapping[str, Any],
) -> dict[str, Any]:
    """Compact exact semantic-definition repair feedback for the next agent."""

    if not isinstance(formalization_manifest, Mapping):
        return {}
    proof_bank_summary = (
        formalization_manifest.get("proof_bank_runtime_memory_summary", {})
        if isinstance(
            formalization_manifest.get("proof_bank_runtime_memory_summary", {}),
            Mapping,
        )
        else {}
    )
    if not proof_bank_summary:
        return {}
    target_mode = str(
        proof_bank_summary.get("recommended_formalizer_target_mode", "") or ""
    ).strip()
    repair_required = bool(
        proof_bank_summary.get(
            "source_theorem_exact_semantic_definition_repair_required",
            False,
        )
        or target_mode == _SOURCE_THEOREM_EXACT_SEMANTIC_REPAIR_MODE
    )
    if not repair_required:
        return {}
    raw_diagnostics = [
        row
        for row in proof_bank_summary.get(
            "source_theorem_exact_candidate_repair_diagnostics",
            [],
        )
        or []
        if isinstance(row, Mapping)
    ]

    def is_semantic_repair_row(row: Mapping[str, Any]) -> bool:
        failure = str(row.get("failure_classification", "") or "")
        trigger = str(row.get("trigger", "") or "")
        gate = str(row.get("proof_body_gate_status", "") or "")
        runtime_queue_status = str(row.get("runtime_queue_status", "") or "")
        return bool(
            failure in _SOURCE_THEOREM_EXACT_SEMANTIC_REPAIR_FAILURES
            or trigger in _SOURCE_THEOREM_EXACT_SEMANTIC_REPAIR_TRIGGERS
            or gate in _SOURCE_THEOREM_EXACT_SEMANTIC_REPAIR_GATES
            or runtime_queue_status
            == _SOURCE_THEOREM_EXACT_SEMANTIC_REPAIR_QUEUE_STATUS
            or row.get("semantic_alignment_blockers")
            or row.get("semantic_definition_risks")
        )

    failure_classifications = [
        str(value).strip()
        for value in proof_bank_summary.get(
            "source_theorem_exact_candidate_failure_classifications",
            [],
        )
        or []
        if str(value).strip()
    ]
    triggers = [
        str(value).strip()
        for value in proof_bank_summary.get(
            "source_theorem_exact_candidate_repair_triggers",
            [],
        )
        or []
        if str(value).strip()
    ]
    target_names = [
        str(value).strip()
        for value in (
            proof_bank_summary.get("source_theorem_exact_candidate_repair_target_names", [])
            or proof_bank_summary.get(
                "source_theorem_exact_proof_body_repair_target_names",
                [],
            )
            or []
        )
        if str(value).strip()
    ]
    semantic_rows = [row for row in raw_diagnostics if is_semantic_repair_row(row)]
    placeholder_symbols = [
        str(value).strip()
        for value in proof_bank_summary.get(
            "source_theorem_exact_candidate_repair_placeholder_symbols",
            [],
        )
        or []
        if str(value).strip()
    ]
    typechecked_candidates = [
        dict(row)
        for row in proof_bank_summary.get(
            "source_theorem_exact_semantic_definition_typechecked_candidates",
            [],
        )
        or []
        if isinstance(row, Mapping)
    ]
    target_ids: list[str] = []

    def add_target_ids(values: Any) -> None:
        for value in _str_tuple(values):
            text = str(value or "").strip()
            if text:
                target_ids.append(text)

    for key in (
        "remaining_theorem_goal_ids",
        "source_theorem_exact_candidate_repair_target_ids",
        "target_ids",
        "target_theorem_goal_ids",
    ):
        add_target_ids(proof_bank_summary.get(key, []))
    for row in formalization_manifest.get("deterministic_theorem_goals", []) or []:
        if isinstance(row, Mapping):
            add_target_ids(row.get("id", ""))
    for row in [*raw_diagnostics, *typechecked_candidates]:
        add_target_ids(
            _runtime_exact_semantic_definition_target_ids(
                row,
                target_theorem_name="",
            )
        )
    if not target_ids:
        add_target_ids(target_names)
    target_ids = list(dict.fromkeys(target_ids))
    for row in raw_diagnostics:
        symbol = str(row.get("placeholder_symbol", "") or "").strip()
        if symbol:
            placeholder_symbols.append(symbol)
    for row in typechecked_candidates:
        symbol = str(row.get("placeholder_symbol", "") or "").strip()
        if symbol:
            placeholder_symbols.append(symbol)
    placeholder_symbols = list(dict.fromkeys(placeholder_symbols))

    def row_target(row: Mapping[str, Any]) -> str:
        return (
            str(row.get("target_theorem_name", "") or "").strip()
            or (target_names[0] if target_names else "")
        )

    def row_key(row: Mapping[str, Any]) -> tuple[str, str]:
        return (
            row_target(row),
            str(row.get("placeholder_symbol", "") or "").strip(),
        )

    def merge_typechecked_candidate(
        row: dict[str, Any],
        candidate: Mapping[str, Any],
    ) -> None:
        candidate_target = row_target(candidate)
        candidate_symbol = str(candidate.get("placeholder_symbol", "") or "").strip()
        if candidate_target and not str(
            row.get("target_theorem_name", "") or ""
        ).strip():
            row["target_theorem_name"] = candidate_target
        if candidate_symbol and not str(
            row.get("placeholder_symbol", "") or ""
        ).strip():
            row["placeholder_symbol"] = candidate_symbol
        scalar_keys = (
            "definition_only_candidate_artifact_path",
            "candidate_artifact_path",
            "semantic_definition_typecheck_evidence_status",
        )
        for key in scalar_keys:
            value = str(candidate.get(key, "") or "").strip()
            if value and not str(row.get(key, "") or "").strip():
                row[key] = value
        for key in ("local_definition_lean_checked", "local_definition_lean_compiled"):
            if candidate.get(key) is not None:
                row[key] = bool(row.get(key, False) or candidate.get(key, False))
        status = str(
            candidate.get("semantic_definition_typecheck_evidence_status", "") or ""
        ).strip()
        if (
            status in _SOURCE_THEOREM_EXACT_SEMANTIC_DEFINITION_TYPECHECKED_STATUSES
            and not str(row.get("runtime_queue_status", "") or "").strip()
        ):
            row["runtime_queue_status"] = (
                "TYPECHECKED_EXACT_DEFINITION_CANDIDATE_REVIEW_REQUIRED"
            )
        if not str(row.get("failure_classification", "") or "").strip():
            row["failure_classification"] = (
                "typechecked_exact_semantic_definition_candidate_review_required"
            )
        row.setdefault(
            "definition_candidate_review_mode",
            "typechecked_candidate_semantic_review_required",
        )
        row.setdefault("source_theorem_kernel_evidence_eligible", False)
        row["source_theorem_exact_semantic_definition_typechecked_candidate"] = {
            key: value
            for key, value in candidate.items()
            if value not in (None, "", [], {})
        }

    semantic_review_failure = next(
        (
            value
            for value in failure_classifications
            if value in _SOURCE_THEOREM_EXACT_SEMANTIC_REPAIR_FAILURES
        ),
        "",
    )
    semantic_review_trigger = next(
        (
            value
            for value in triggers
            if value in _SOURCE_THEOREM_EXACT_SEMANTIC_REPAIR_TRIGGERS
        ),
        "",
    )
    if semantic_rows:
        selected_rows = semantic_rows
    elif semantic_review_failure or semantic_review_trigger:
        selected_rows = [
            {
                "target_theorem_name": target_names[0] if target_names else "",
                "trigger": semantic_review_trigger
                or "EXACT_SOURCE_SEMANTIC_ALIGNMENT_REVIEW_REQUIRED",
                "failure_classification": semantic_review_failure
                or "source_theorem_exact_semantic_definition_repair_required",
                "runtime_queue_status": (
                    _SOURCE_THEOREM_EXACT_SEMANTIC_REPAIR_QUEUE_STATUS
                ),
                "proof_body_gate_status": "SEMANTIC_REVIEW_REQUIRED_BEFORE_PROOF_BODY",
                "source_theorem_kernel_evidence_eligible": False,
                "adapter_kernel_verified": bool(
                    proof_bank_summary.get(
                        "source_theorem_proof_body_adapter_kernel_verified",
                        False,
                    )
                ),
                "kernel_verified_source_theorem_proof_body_adapter_ids": list(
                    proof_bank_summary.get(
                        "kernel_verified_source_theorem_proof_body_adapter_ids",
                        [],
                    )
                    or []
                )[:5],
                "recommended_repair_tasks": [
                    "review or kernel-verify exact semantic definitions before retrying the exact proof body",
                    "preserve verified adapter rows as context only until the source theorem itself passes local Lean/AXLE",
                ],
            }
        ]
    else:
        selected_rows = raw_diagnostics[:3]
    keyed_rows: dict[tuple[str, str], dict[str, Any]] = {}
    unkeyed_rows: list[dict[str, Any]] = []
    for row in selected_rows:
        compactable = dict(row)
        key = row_key(compactable)
        if key[0] and key[1]:
            keyed_rows.setdefault(key, compactable)
        else:
            unkeyed_rows.append(compactable)
    for candidate in typechecked_candidates:
        key = row_key(candidate)
        if not key[0] or not key[1]:
            continue
        row = keyed_rows.setdefault(
            key,
            {
                "target_theorem_name": key[0],
                "placeholder_symbol": key[1],
                "trigger": "EXACT_SOURCE_SEMANTIC_DEFINITION_TYPECHECKED_CANDIDATE_REVIEW",
                "failure_classification": (
                    "typechecked_exact_semantic_definition_candidate_review_required"
                ),
                "runtime_queue_status": (
                    "TYPECHECKED_EXACT_DEFINITION_CANDIDATE_REVIEW_REQUIRED"
                ),
                "proof_body_gate_status": (
                    "SEMANTIC_REVIEW_REQUIRED_BEFORE_PROOF_BODY"
                ),
                "source_theorem_kernel_evidence_eligible": False,
            },
        )
        merge_typechecked_candidate(row, candidate)
    default_target = target_names[0] if target_names else ""
    for symbol in placeholder_symbols:
        if not default_target:
            continue
        key = (default_target, symbol)
        keyed_rows.setdefault(
            key,
            {
                "target_theorem_name": default_target,
                "placeholder_symbol": symbol,
                "trigger": "EXACT_SOURCE_SEMANTIC_DEFINITION_REPAIR_REQUIRED",
                "failure_classification": (
                    "source_theorem_exact_semantic_definition_repair_required"
                ),
                "runtime_queue_status": (
                    _SOURCE_THEOREM_EXACT_SEMANTIC_REPAIR_QUEUE_STATUS
                ),
                "proof_body_gate_status": (
                    "SEMANTIC_REVIEW_REQUIRED_BEFORE_PROOF_BODY"
                ),
                "source_theorem_kernel_evidence_eligible": False,
                "recommended_repair_tasks": [
                    "retrieve, review, or formalize the exact semantic definition for this placeholder before retrying proof-body tactics"
                ],
            },
        )
    selected_rows = [*keyed_rows.values(), *unkeyed_rows]
    compact_keys = (
        "target_theorem_name",
        "target_ids",
        "target_theorem_goal_ids",
        "placeholder_symbol",
        "trigger",
        "failure_classification",
        "runtime_queue_status",
        "candidate_artifact_path",
        "candidate_source_file",
        "definition_only_candidate_artifact_path",
        "definition_candidate_review_mode",
        "semantic_definition_typecheck_evidence_status",
        "local_definition_lean_checked",
        "local_definition_lean_compiled",
        "proof_body_gate_status",
        "proof_body_goal_reached",
        "source_theorem_kernel_evidence_eligible",
        "source_theorem_target_identity_status",
        "adapter_kernel_verified",
        "kernel_verified_source_theorem_proof_body_adapter_ids",
        "verified_source_theorem_proof_body_adapter_artifact_paths",
        "verified_source_theorem_proof_body_adapter_declarations",
        "semantic_alignment_constraints",
        "semantic_alignment_blockers",
        "semantic_definition_risks",
        "environment_repair_status",
        "candidate_lean_project_hint",
        "candidate_source_file",
        "unavailable_module_prefix",
        "dependency_fetch_required",
        "ready_to_rerun_lean_repair",
        "recommended_commands",
        "recommended_next_action",
        "local_lean_diagnostics",
        "source_environment_repair_task_id",
        "recommended_repair_tasks",
        "diagnostics",
        "source_theorem_exact_semantic_definition_typechecked_candidate",
    )
    diagnostics: list[dict[str, Any]] = []
    for row in selected_rows[:8]:
        compact: dict[str, Any] = {
            key: row[key]
            for key in compact_keys
            if key in row and row.get(key) not in (None, "", [], {})
        }
        compact_target_ids = _runtime_exact_semantic_definition_target_ids(
            row,
            target_theorem_name="",
        )
        if not compact_target_ids:
            compact_target_ids = list(target_ids)
        if compact_target_ids:
            compact["target_ids"] = list(dict.fromkeys(compact_target_ids))
        if compact:
            diagnostics.append(compact)
    proof_body_gate_statuses = list(
        dict.fromkeys(
            str(row.get("proof_body_gate_status", "") or "").strip()
            for row in diagnostics
            if str(row.get("proof_body_gate_status", "") or "").strip()
        )
    )
    runtime_queue_statuses = list(
        dict.fromkeys(
            str(row.get("runtime_queue_status", "") or "").strip()
            for row in diagnostics
            if str(row.get("runtime_queue_status", "") or "").strip()
        )
    )
    return {
        "feedback_kind": (
            "critic_source_theorem_exact_semantic_definition_repair_feedback"
        ),
        "source": "proof_bank_runtime_memory_summary",
        "source_theorem_exact_semantic_definition_repair_required": True,
        "recommended_formalizer_target_mode": target_mode,
        "recommended_source_theorem_integration_action": str(
            proof_bank_summary.get(
                "recommended_source_theorem_integration_action",
                "",
            )
            or ""
        ),
        "target_names": list(dict.fromkeys(target_names)),
        "failure_classifications": list(dict.fromkeys(failure_classifications)),
        "triggers": list(dict.fromkeys(triggers)),
        "target_ids": list(dict.fromkeys(target_ids)),
        "proof_body_gate_statuses": proof_body_gate_statuses,
        "runtime_queue_statuses": runtime_queue_statuses,
        "source_theorem_ready_for_exact_proof_body": bool(
            proof_bank_summary.get("source_theorem_ready_for_exact_proof_body", False)
        ),
        "source_theorem_proof_body_adapter_kernel_verified": bool(
            proof_bank_summary.get(
                "source_theorem_proof_body_adapter_kernel_verified",
                False,
            )
        ),
        "kernel_verified_source_theorem_proof_body_adapter_ids": list(
            proof_bank_summary.get(
                "kernel_verified_source_theorem_proof_body_adapter_ids",
                [],
            )
            or []
        )[:5],
        "diagnostics": diagnostics,
        "required_behavior": (
            "Review, retrieve, import, or formalize the exact source-theorem semantic "
            "definitions before spending proof-body budget. A kernel-verified "
            "source-to-bridge adapter is routing context only; do not claim source "
            "theorem proof until the exact theorem is checked by local Lean/AXLE."
        ),
        "acceptance_gate": (
            "proof_bank_runtime_memory_summary records reviewed or kernel-verified "
            "exact semantic definitions, then the exact source theorem proof-body "
            "executor reruns and local Lean/AXLE verifies the intended declaration"
        ),
        "proof_evidence_status": (
            "CRITIC_EXACT_SEMANTIC_DEFINITION_REPAIR_FEEDBACK_NOT_PROOF_EVIDENCE"
        ),
        "proof_evidence_boundary": KERNEL_PROOF_BOUNDARY,
    }


def _critic_semantic_anchor_blocker_feedback(
    formal_blocker_resource_requests: Sequence[Mapping[str, Any]],
) -> dict[str, Any]:
    blockers: list[dict[str, Any]] = []
    anchors: list[str] = []
    for row in formal_blocker_resource_requests:
        if not isinstance(row, Mapping):
            continue
        blocker_kind = str(row.get("blocker_kind", "") or "")
        blocker = str(row.get("blocker", "") or "")
        haystack = f"{blocker_kind} {blocker}".lower()
        if not (
            "semantic_anchor" in haystack
            or "semantic anchor" in haystack
            or "anchor binder" in haystack
        ):
            continue
        blockers.append(
            {
                "request_id": str(row.get("request_id", "") or ""),
                "source": str(row.get("source", "") or ""),
                "blocker_kind": blocker_kind,
                "blocker": blocker,
                "next_owner": str(row.get("next_owner", "") or ""),
                "proof_evidence_status": str(
                    row.get("proof_evidence_status", "") or ""
                ),
            }
        )
        for match in re.finditer(
            r"(?:anchor binder|semantic anchor(?: reference)?(?: binder)?)\s+"
            r"`?([A-Za-z_][A-Za-z0-9_']*)`?",
            blocker,
        ):
            anchors.append(match.group(1))
        for quoted in re.findall(r"`([A-Za-z_][A-Za-z0-9_']*)`", blocker):
            anchors.append(quoted)
    ignored_anchor_tokens = {
        "a",
        "an",
        "binder",
        "binders",
        "name",
        "names",
        "reference",
        "references",
        "the",
    }
    anchors = list(
        dict.fromkeys(
            anchor
            for anchor in anchors
            if anchor and anchor.lower() not in ignored_anchor_tokens
        )
    )
    if not blockers and not anchors:
        return {}
    return {
        "semantic_alignment_blockers": blockers,
        "missing_semantic_anchor_references": anchors,
        "proof_evidence_status": (
            "CRITIC_SEMANTIC_ANCHOR_BLOCKER_FEEDBACK_NOT_PROOF_EVIDENCE"
        ),
        "proof_evidence_boundary": KERNEL_PROOF_BOUNDARY,
    }


def _critic_repair_feedback(
    *,
    question: OpenResearchQuestion,
    critic_round: int,
    max_critic_repair_rounds: int,
    retrieval_manifest: Mapping[str, Any],
    theory_packet: Mapping[str, Any],
    simulation_manifest: Mapping[str, Any],
    algorithm_manifest: Mapping[str, Any],
    formalization_manifest: Mapping[str, Any],
    agenda: list[dict[str, Any]],
) -> dict[str, Any]:
    formal_counts = formalization_manifest.get("counts", {}) if isinstance(formalization_manifest, Mapping) else {}
    formalizer_local_lean_contract = (
        _critic_local_lean_repair_contract_from_formalization_manifest(
            formalization_manifest
        )
    )
    formalizer_candidate_diagnostics = (
        _critic_candidate_diagnostics_from_formalization_manifest(
            formalization_manifest
        )
    )
    formal_blocker_resource_requests = _critic_formal_blocker_resource_requests(
        formalization_manifest=formalization_manifest,
        agenda=agenda,
    )
    source_to_bridge_premise_feedback = (
        _critic_source_to_bridge_premise_derivation_feedback(
            formalization_manifest
        )
    )
    source_theorem_proof_body_adapter_feedback = (
        _critic_source_theorem_proof_body_adapter_feedback(
            formalization_manifest
        )
    )
    exact_semantic_definition_repair_feedback = (
        _critic_source_theorem_exact_semantic_definition_repair_feedback(
            formalization_manifest
        )
    )
    if source_theorem_proof_body_adapter_feedback:
        formal_blocker_resource_requests = _merge_formal_blocker_resource_requests(
            _formal_blocker_resource_requests_from_source_theorem_proof_body_adapter_feedback(
                source_theorem_proof_body_adapter_feedback
            ),
            formal_blocker_resource_requests,
        )
    if exact_semantic_definition_repair_feedback:
        formal_blocker_resource_requests = _merge_formal_blocker_resource_requests(
            _formal_blocker_resource_requests_from_exact_semantic_definition_repair_feedback(
                exact_semantic_definition_repair_feedback
            ),
            formal_blocker_resource_requests,
        )
    if formalizer_local_lean_contract:
        local_lean_manifest_context = dict(formalization_manifest)
        local_lean_manifest_context["question"] = {
            "id": question.id,
            "title": question.title,
        }
        formal_blocker_resource_requests = _merge_formal_blocker_resource_requests(
            formal_blocker_resource_requests,
            _formal_blocker_resource_requests_from_unavailable_imports(
                local_lean_repair_contract=formalizer_local_lean_contract,
                manifest=local_lean_manifest_context,
                diagnostics=formalizer_candidate_diagnostics,
                source="critic_local_lean_formalization_feedback",
            ),
        )
    semantic_anchor_blocker_feedback = _critic_semantic_anchor_blocker_feedback(
        formal_blocker_resource_requests
    )
    if source_to_bridge_premise_feedback and semantic_anchor_blocker_feedback:
        source_to_bridge_premise_feedback = dict(source_to_bridge_premise_feedback)
        blockers = semantic_anchor_blocker_feedback.get(
            "semantic_alignment_blockers", []
        )
        if blockers:
            source_to_bridge_premise_feedback["semantic_alignment_blockers"] = (
                blockers
            )
        merged_anchor_references = list(
            dict.fromkeys(
                [
                    *(
                        source_to_bridge_premise_feedback.get(
                            "missing_semantic_anchor_references", []
                        )
                        or []
                    ),
                    *(
                        semantic_anchor_blocker_feedback.get(
                            "missing_semantic_anchor_references", []
                        )
                        or []
                    ),
                ]
            )
        )
        source_to_bridge_premise_feedback[
            "missing_semantic_anchor_references"
        ] = merged_anchor_references
    required_repair = (
        "Revise theorem statements, assumptions, estimator specification, or proof plan "
        "to address formal gaps and non-kernel proof feedback. Do not claim proof evidence "
        "unless AXLE/local Lean kernel verification closes the intended claim."
    )
    feedback = {
        "feedback_source": "CriticEvaluator",
        "failure_classification": "critic_requested_theory_revision",
        "question_id": question.id,
        "critic_repair_round": critic_round,
        "next_critic_repair_round": critic_round + 1,
        "max_critic_repair_rounds": max_critic_repair_rounds,
        "theory_packet_id": str(theory_packet.get("packet_id", "")),
        "retrieval_memory_manifest_id": str(retrieval_manifest.get("manifest_id", "")),
        "simulation_manifest_id": str(simulation_manifest.get("manifest_id", "")),
        "algorithm_sandbox_manifest_id": str(algorithm_manifest.get("manifest_id", "")),
        "formalization_manifest_id": str(formalization_manifest.get("manifest_id", "")),
        "formalization_counts": dict(formal_counts) if isinstance(formal_counts, Mapping) else {},
        "high_priority_agenda": [
            _compact_agenda_item(row)
            for row in agenda
            if str(row.get("priority", "")).lower() == "high"
        ],
        "formal_subclaim_feedback": [
            _compact_formal_subclaim_feedback(row)
            for row in formalization_manifest.get("formal_subclaims", [])[:8]
            if isinstance(row, Mapping)
        ],
        "proof_state_feedback_manifest_id": str(
            formalization_manifest.get("proof_state_feedback_manifest_id", "")
        ),
        "required_revision": required_repair,
        "required_repair": required_repair,
        "proof_evidence_boundary": KERNEL_PROOF_BOUNDARY,
    }
    if formal_blocker_resource_requests:
        feedback["formal_blocker_resource_requests"] = formal_blocker_resource_requests
    if semantic_anchor_blocker_feedback:
        feedback["semantic_anchor_blocker_feedback"] = semantic_anchor_blocker_feedback
    if source_to_bridge_premise_feedback:
        feedback["source_to_bridge_premise_derivation_feedback"] = (
            source_to_bridge_premise_feedback
        )
        diagnostics = source_to_bridge_premise_feedback.get("diagnostics", [])
        if diagnostics:
            feedback["source_to_bridge_premise_derivation_diagnostics"] = diagnostics
        missing_anchor_references = source_to_bridge_premise_feedback.get(
            "missing_semantic_anchor_references", []
        )
        if missing_anchor_references:
            feedback["missing_semantic_anchor_references"] = missing_anchor_references
    elif semantic_anchor_blocker_feedback.get("missing_semantic_anchor_references"):
        feedback["missing_semantic_anchor_references"] = (
            semantic_anchor_blocker_feedback["missing_semantic_anchor_references"]
        )
    if formalizer_local_lean_contract:
        feedback["local_lean_repair_contract"] = formalizer_local_lean_contract
    if formalizer_candidate_diagnostics:
        feedback["candidate_diagnostics"] = formalizer_candidate_diagnostics
    if source_theorem_proof_body_adapter_feedback:
        feedback["source_theorem_proof_body_adapter_feedback"] = (
            source_theorem_proof_body_adapter_feedback
        )
    if exact_semantic_definition_repair_feedback:
        feedback["source_theorem_exact_semantic_definition_repair_feedback"] = (
            exact_semantic_definition_repair_feedback
        )
    return feedback


def _critic_formal_blocker_resource_requests(
    *,
    formalization_manifest: Mapping[str, Any],
    agenda: Sequence[Mapping[str, Any]],
) -> list[dict[str, Any]]:
    """Turn formal blocker rows into typed retriever/prover resource requests."""

    if not isinstance(formalization_manifest, Mapping):
        return []
    target_ids = [
        str(row.get("id", "") or "").strip()
        for row in formalization_manifest.get("deterministic_theorem_goals", []) or []
        if isinstance(row, Mapping) and str(row.get("id", "") or "").strip()
    ]
    request_rows: list[dict[str, Any]] = []
    seen: set[str] = set()

    def add_request(
        *,
        source: str,
        blocker_kind: str,
        blocker: str,
        next_owner: str,
        target_ids_override: Sequence[Any] = (),
    ) -> None:
        blocker = blocker.strip()
        blocker_kind = blocker_kind.strip() or "formal_blocker"
        if not blocker:
            return
        fingerprint = stable_hash([source, blocker_kind, blocker, next_owner])[:20]
        if fingerprint in seen:
            return
        seen.add(fingerprint)
        request_rows.append(
            {
                "request_id": f"formal_blocker_resource_request:{fingerprint}",
                "source": source,
                "blocker_kind": blocker_kind,
                "blocker": blocker,
                "next_owner": next_owner.strip() or "Formalizer/ProofEngineer",
                "target_ids": [
                    str(value).strip()
                    for value in (target_ids_override or target_ids)
                    if str(value).strip()
                ],
                "formal_source_queries": _formal_blocker_resource_request_queries(
                    blocker,
                    blocker_kind=blocker_kind,
                    target_ids=target_ids_override or target_ids,
                ),
                "recommended_tools": [
                    "formal_source_retriever",
                    "proof_search",
                    "lean_lsp_mcp_when_configured",
                    "local_lean_or_axle",
                ],
                "required_resolution": (
                    "Retrieve or identify a verified local declaration/import, "
                    "formalize a smaller semantic primitive, or keep the theorem as "
                    "FORMAL_GAP with the exact missing API/definition named. Do not "
                    "emit an executable candidate that reuses an unresolved blocker."
                ),
                "proof_evidence_status": (
                    "FORMAL_BLOCKER_RESOURCE_REQUEST_NOT_PROOF_EVIDENCE"
                ),
                "proof_evidence_boundary": KERNEL_PROOF_BOUNDARY,
            }
        )

    for row in formalization_manifest.get("llm_formalizer_gap_taxonomy", []) or []:
        if not isinstance(row, Mapping):
            continue
        add_request(
            source="llm_formalizer_gap_taxonomy",
            blocker_kind=str(row.get("kind", "") or ""),
            blocker=str(row.get("gap", "") or ""),
            next_owner=str(row.get("next_owner", "") or ""),
        )

    proof_bank_memory_summary = (
        formalization_manifest.get("proof_bank_runtime_memory_summary", {})
        if isinstance(
            formalization_manifest.get("proof_bank_runtime_memory_summary", {}),
            Mapping,
        )
        else {}
    )
    if proof_bank_memory_summary.get(
        "source_theorem_candidate_materialization_required", False
    ):
        materialization_targets = [
            str(value).strip()
            for value in proof_bank_memory_summary.get(
                "source_theorem_candidate_materialization_required_target_names",
                [],
            )
            or []
            if str(value).strip()
        ]
        materialization_statuses = [
            str(value).strip()
            for value in proof_bank_memory_summary.get(
                "source_theorem_candidate_materialization_required_statuses",
                [],
            )
            or []
            if str(value).strip()
        ]
        missing_symbols = [
            str(value).strip()
            for value in proof_bank_memory_summary.get(
                "source_theorem_candidate_materialization_missing_formal_symbols",
                [],
            )
            or []
            if str(value).strip()
        ]
        materialization_contract = str(
            proof_bank_memory_summary.get(
                "source_theorem_candidate_materialization_contract", ""
            )
            or ""
        ).strip()
        blocker_parts = [
            materialization_contract
            or (
                "Materialize an exact source-theorem Lean candidate artifact "
                "before signature probes or proof-body execution can run."
            ),
        ]
        if materialization_statuses:
            blocker_parts.append(
                "signature_probe_statuses="
                + ", ".join(materialization_statuses[:4])
            )
        if missing_symbols:
            blocker_parts.append(
                "missing_formal_symbols=" + ", ".join(missing_symbols[:8])
            )
        add_request(
            source="proof_bank_runtime_memory_summary",
            blocker_kind="SOURCE_THEOREM_CANDIDATE_MATERIALIZATION_REQUIRED",
            blocker="; ".join(blocker_parts),
            next_owner="Formalizer/ProofEngineer/LeanProver",
            target_ids_override=materialization_targets,
        )

    for row in agenda:
        if not isinstance(row, Mapping):
            continue
        trigger = str(row.get("trigger", "") or "")
        agenda_id = str(row.get("id", "") or "")
        owner = str(row.get("owner_subsystem", "") or "")
        if not (
            agenda_id.startswith("formal_gap:")
            or trigger.startswith(("SOURCE_", "FORMAL_GAP", "POST_RUNTIME_PROOF"))
            or "ProofEngineer" in owner
            or "LeanProver" in owner
        ):
            continue
        add_request(
            source="critic_next_action_agenda",
            blocker_kind=trigger or agenda_id,
            blocker=str(row.get("action", "") or ""),
            next_owner=owner,
            target_ids_override=[
                str(value).strip()
                for value in row.get("target_ids", []) or []
                if str(value).strip()
            ],
        )

    return request_rows[:FORMAL_BLOCKER_RESOURCE_REQUEST_LIMIT]


def _formal_blocker_resource_request_queries(
    blocker: str,
    *,
    blocker_kind: str,
    target_ids: Sequence[Any],
) -> list[str]:
    target_text = " ".join(str(value).strip() for value in target_ids if str(value).strip())
    base = " ".join(part for part in (blocker_kind, blocker, target_text) if part).strip()
    queries: list[str] = []
    if base:
        queries.append(base)
    identifier_pattern = re.compile(
        r"`([^`]+)`|\b([A-Za-z_][A-Za-z0-9_'.]*\.[A-Za-z0-9_'.]+)\b"
    )
    for match in identifier_pattern.finditer(blocker):
        identifier = str(match.group(1) or match.group(2) or "").strip()
        query = f"{identifier} Lean declaration" if identifier else ""
        if query and query not in queries:
            queries.append(query)
    for phrase in re.findall(r"\b[A-Z][A-Za-z0-9_]*(?:[A-Z][A-Za-z0-9_]*)+\b", blocker):
        query = f"{phrase} Lean definition"
        if query not in queries:
            queries.append(query)
    return queries[:5]


def _lean_import_modules_from_artifact_path(artifact_path: str) -> list[str]:
    path_text = str(artifact_path or "").strip()
    if not path_text:
        return []
    path = Path(path_text)
    if not path.exists() or not path.is_file():
        return []
    try:
        source = path.read_text(encoding="utf-8")
    except OSError:
        return []
    imports: list[str] = []
    seen: set[str] = set()
    for line in source.splitlines()[:80]:
        match = re.match(r"^\s*import\s+(?P<modules>.+?)\s*$", line)
        if not match:
            continue
        for module in match.group("modules").split():
            module = module.strip()
            if module and module not in seen:
                seen.add(module)
                imports.append(module)
    return imports[:8]


def _formal_blocker_resource_requests_from_source_theorem_proof_body_adapter_feedback(
    feedback: Mapping[str, Any] | None,
) -> list[dict[str, Any]]:
    """Convert adapter bridge residuals into typed prover/RAG work requests."""

    if not isinstance(feedback, Mapping):
        return []
    diagnostics = [
        row
        for row in feedback.get("diagnostics", []) or []
        if isinstance(row, Mapping)
    ]
    if not diagnostics:
        return []
    default_targets = [
        str(value).strip()
        for value in feedback.get("target_names", []) or []
        if str(value).strip()
    ]
    rows: list[dict[str, Any]] = []
    for diagnostic in diagnostics[:4]:
        if bool(diagnostic.get("adapter_kernel_verified", False)):
            continue
        target_ids = [
            str(value).strip()
            for value in [
                diagnostic.get("target_theorem_name", ""),
                *default_targets,
            ]
            if str(value).strip()
        ]
        target_ids = list(dict.fromkeys(target_ids))
        failure = str(diagnostic.get("failure_classification", "") or "").strip()
        artifact_path = str(
            diagnostic.get("adapter_candidate_artifact_path", "") or ""
        ).strip()
        declaration = str(diagnostic.get("adapter_declaration_name", "") or "").strip()
        diagnostic_lines = [
            str(value)
            for value in diagnostic.get("diagnostics", []) or []
            if str(value).strip()
        ]
        diagnostic_text = "\n".join(diagnostic_lines)
        unavailable_import = str(
            diagnostic.get("unavailable_import", "") or ""
        ).strip()
        candidate_imports = [
            str(value).strip()
            for value in diagnostic.get("adapter_candidate_imports", []) or []
            if str(value).strip()
        ]
        exact_import_prefixes = [unavailable_import] if unavailable_import else []
        if not exact_import_prefixes:
            exact_import_prefixes = _formalizer_unavailable_import_prefixes_from_diagnostics(
                [
                    {
                        "local_lean_stdout_excerpt": diagnostic_text,
                        "local_lean_stderr_excerpt": diagnostic_text,
                    }
                ]
            )
        candidate_import_prefixes = list(dict.fromkeys(candidate_imports))
        candidate_import_source = (
            "adapter_candidate_imports" if candidate_import_prefixes else ""
        )
        if (
            not exact_import_prefixes
            and not candidate_import_prefixes
            and failure == "adapter_lean_import_environment_missing"
        ):
            candidate_import_prefixes = _lean_import_modules_from_artifact_path(
                artifact_path
            )
            if candidate_import_prefixes:
                candidate_import_source = "adapter_candidate_artifact_imports"
        import_requests: list[tuple[str, bool]] = [
            (module, True)
            for module in list(dict.fromkeys(exact_import_prefixes))[:2]
        ]
        if not import_requests:
            import_requests = [
                (module, False)
                for module in list(dict.fromkeys(candidate_import_prefixes))[:4]
            ]
        if import_requests:
            for module, exact_unavailable in import_requests:
                blocker_kind = (
                    "source_theorem_proof_body_adapter_unavailable_import"
                    if exact_unavailable
                    else "source_theorem_proof_body_adapter_candidate_import_resolution"
                )
                blocker = (
                    f"{module} unavailable import while checking source-theorem "
                    "proof-body adapter"
                    if exact_unavailable
                    else f"{module} appears in a source-theorem proof-body "
                    "adapter candidate whose import diagnostic was truncated"
                )
                if declaration:
                    blocker += f" `{declaration}`"
                if artifact_path and not exact_unavailable:
                    blocker += f" at {artifact_path}"
                if exact_unavailable:
                    blocker += (
                        ". Retrieve or select a verified local import/declaration "
                        "in the configured Lean project, or keep the adapter/source "
                        "theorem as FORMAL_GAP with the missing dependency named."
                    )
                else:
                    blocker += (
                        ". Verify this candidate import in the configured Lean "
                        "project, recover the exact missing module from local Lean "
                        "or LSP diagnostics, or keep the adapter/source theorem as "
                        "FORMAL_GAP with the unresolved dependency named."
                    )
                fingerprint = stable_hash(
                    [
                        "critic_source_theorem_proof_body_adapter_feedback",
                        blocker_kind,
                        module,
                        exact_unavailable,
                        target_ids,
                        "" if exact_unavailable else artifact_path,
                    ]
                )[:20]
                formal_source_queries = [
                    f"{module} Lean import",
                    *_formal_blocker_resource_request_queries(
                        blocker,
                        blocker_kind=blocker_kind,
                        target_ids=target_ids,
                    ),
                ]
                rows.append(
                    {
                        "request_id": (
                            f"formal_blocker_resource_request:{fingerprint}"
                        ),
                        "source": (
                            "critic_source_theorem_proof_body_adapter_feedback"
                        ),
                        "blocker_kind": blocker_kind,
                        "blocker": blocker,
                        "next_owner": "Formalizer/ProofEngineer/LeanProver",
                        "target_ids": target_ids,
                        "unavailable_import": module if exact_unavailable else "",
                        "candidate_import": "" if exact_unavailable else module,
                        "unavailable_import_exact": exact_unavailable,
                        "import_resolution_source": (
                            "adapter_unavailable_import_diagnostic"
                            if exact_unavailable
                            else candidate_import_source
                        ),
                        "adapter_candidate_artifact_paths": (
                            [artifact_path] if artifact_path else []
                        ),
                        "adapter_declaration_name": declaration,
                        "formal_source_queries": list(
                            dict.fromkeys(formal_source_queries)
                        )[:5],
                        "recommended_tools": [
                            "formal_source_retriever",
                            "lean_lsp_mcp_when_configured",
                            "local_lean_or_axle",
                        ],
                        "required_resolution": (
                            "Replace the unavailable adapter import with a verified "
                            "local import/declaration, derive a smaller source-to-bridge "
                            "primitive, or keep the adapter/source theorem as FORMAL_GAP. "
                            "Do not repeat the unresolved import."
                            if exact_unavailable
                            else (
                                "Use formal-source retrieval, Lean LSP/MCP, or local "
                                "Lean to determine whether this candidate import is "
                                "available in the configured project and recover the "
                                "exact unavailable module before retrying the adapter."
                            )
                        ),
                        "proof_evidence_status": (
                            "FORMAL_BLOCKER_RESOURCE_REQUEST_NOT_PROOF_EVIDENCE"
                        ),
                        "proof_evidence_boundary": KERNEL_PROOF_BOUNDARY,
                    }
                )
            continue
        blocker_parts = [
            "Source-theorem proof-body adapter did not produce kernel-verified "
            "adapter evidence"
        ]
        if failure:
            blocker_parts.append(f"failure_classification={failure}")
        if declaration:
            blocker_parts.append(f"adapter_declaration={declaration}")
        if artifact_path:
            blocker_parts.append(f"artifact={artifact_path}")
        if diagnostic_lines:
            blocker_parts.append("diagnostic=" + diagnostic_lines[0][:320])
        blocker = "; ".join(blocker_parts)
        fingerprint = stable_hash(
            [
                "critic_source_theorem_proof_body_adapter_feedback",
                failure or "source_theorem_proof_body_adapter_unverified",
                target_ids,
                artifact_path,
                declaration,
            ]
        )[:20]
        rows.append(
            {
                "request_id": f"formal_blocker_resource_request:{fingerprint}",
                "source": "critic_source_theorem_proof_body_adapter_feedback",
                "blocker_kind": (
                    failure or "source_theorem_proof_body_adapter_unverified"
                ),
                "blocker": blocker,
                "next_owner": "Formalizer/ProofEngineer/LeanProver",
                "target_ids": target_ids,
                "formal_source_queries": _formal_blocker_resource_request_queries(
                    blocker,
                    blocker_kind=(
                        failure or "source_theorem_proof_body_adapter_unverified"
                    ),
                    target_ids=target_ids,
                ),
                "recommended_tools": [
                    "formal_source_retriever",
                    "proof_search",
                    "lean_lsp_mcp_when_configured",
                    "local_lean_or_axle",
                ],
                "required_resolution": (
                    "Strengthen the source-to-bridge adapter by deriving bridge "
                    "premises from exact source hypotheses, retrieve/prove any "
                    "missing smaller primitive, rerun local Lean/AXLE, or keep the "
                    "source theorem as FORMAL_GAP with the adapter blocker named."
                ),
                "proof_evidence_status": (
                    "FORMAL_BLOCKER_RESOURCE_REQUEST_NOT_PROOF_EVIDENCE"
                ),
                "proof_evidence_boundary": KERNEL_PROOF_BOUNDARY,
            }
        )
    return rows


def _formal_blocker_resource_requests_from_exact_semantic_definition_repair_feedback(
    feedback: Mapping[str, Any] | None,
) -> list[dict[str, Any]]:
    """Convert exact semantic-definition review blockers into typed RAG/prover work."""

    if not isinstance(feedback, Mapping):
        return []
    if not feedback.get("source_theorem_exact_semantic_definition_repair_required"):
        return []
    default_targets = [
        str(value).strip()
        for value in feedback.get("target_names", []) or []
        if str(value).strip()
    ]
    diagnostics = [
        row
        for row in feedback.get("diagnostics", []) or []
        if isinstance(row, Mapping)
    ]
    if not diagnostics:
        diagnostics = [
            {
                "target_theorem_name": target,
                "failure_classification": (
                    "source_theorem_exact_semantic_definition_repair_required"
                ),
            }
            for target in default_targets[:3]
        ] or [
            {
                "failure_classification": (
                    "source_theorem_exact_semantic_definition_repair_required"
                )
            }
        ]
    rows: list[dict[str, Any]] = []
    for diagnostic in diagnostics[:8]:
        target_ids = [
            str(value).strip()
            for value in [
                diagnostic.get("target_theorem_name", ""),
                *default_targets,
            ]
            if str(value).strip()
        ]
        target_ids = list(dict.fromkeys(target_ids))
        failure = str(diagnostic.get("failure_classification", "") or "").strip()
        trigger = str(diagnostic.get("trigger", "") or "").strip()
        placeholder_symbol = str(
            diagnostic.get("placeholder_symbol", "") or ""
        ).strip()
        gate = str(diagnostic.get("proof_body_gate_status", "") or "").strip()
        runtime_queue_status = str(
            diagnostic.get("runtime_queue_status", "") or ""
        ).strip()
        environment_repair_status = str(
            diagnostic.get("environment_repair_status", "") or ""
        ).strip()
        candidate_lean_project_hint = str(
            diagnostic.get("candidate_lean_project_hint", "") or ""
        ).strip()
        candidate_source_file = str(
            diagnostic.get("candidate_source_file", "") or ""
        ).strip()
        unavailable_module_prefix = str(
            diagnostic.get("unavailable_module_prefix", "") or ""
        ).strip()
        recommended_next_action = str(
            diagnostic.get("recommended_next_action", "") or ""
        ).strip()
        recommended_commands = [
            str(value).strip()
            for value in diagnostic.get("recommended_commands", []) or []
            if str(value).strip()
        ]
        candidate_path = str(
            diagnostic.get("candidate_artifact_path", "") or ""
        ).strip()
        semantic_blockers = [
            str(value).strip()
            for value in diagnostic.get("semantic_alignment_blockers", []) or []
            if str(value).strip()
        ]
        adapter_ids = [
            str(value).strip()
            for value in (
                diagnostic.get(
                    "kernel_verified_source_theorem_proof_body_adapter_ids",
                    [],
                )
                or feedback.get(
                    "kernel_verified_source_theorem_proof_body_adapter_ids",
                    [],
                )
                or []
            )
            if str(value).strip()
        ]
        blocker_parts = [
            "Exact source-theorem proof-body execution is blocked until exact "
            "semantic definitions are reviewed, imported, or kernel-verified"
        ]
        if placeholder_symbol:
            blocker_parts.append(f"placeholder_symbol={placeholder_symbol}")
        if failure:
            blocker_parts.append(f"failure_classification={failure}")
        if gate:
            blocker_parts.append(f"proof_body_gate_status={gate}")
        if runtime_queue_status:
            blocker_parts.append(f"runtime_queue_status={runtime_queue_status}")
        if environment_repair_status:
            blocker_parts.append(
                f"environment_repair_status={environment_repair_status}"
            )
        if unavailable_module_prefix:
            blocker_parts.append(
                f"unavailable_module_prefix={unavailable_module_prefix}"
            )
        if candidate_lean_project_hint:
            blocker_parts.append(
                f"candidate_lean_project_hint={candidate_lean_project_hint}"
            )
        if candidate_source_file:
            blocker_parts.append(f"candidate_source_file={candidate_source_file}")
        if recommended_next_action:
            blocker_parts.append(
                f"recommended_next_action={recommended_next_action}"
            )
        if candidate_path:
            blocker_parts.append(f"candidate_artifact={candidate_path}")
        if recommended_commands:
            blocker_parts.append(
                "recommended_commands=" + ", ".join(recommended_commands[:3])
            )
        if semantic_blockers:
            blocker_parts.append(
                "semantic_alignment_blockers="
                + ", ".join(semantic_blockers[:4])
            )
        if adapter_ids:
            blocker_parts.append(
                "verified_adapter_context_ids=" + ", ".join(adapter_ids[:4])
            )
        blocker = "; ".join(blocker_parts)
        blocker_kind = (
            environment_repair_status
            or failure
            or trigger
            or "source_theorem_exact_semantic_definition_repair_required"
        )
        fingerprint = stable_hash(
            [
                "critic_source_theorem_exact_semantic_definition_repair_feedback",
                blocker_kind,
                placeholder_symbol,
                gate,
                environment_repair_status,
                unavailable_module_prefix,
                candidate_lean_project_hint,
                candidate_source_file,
                target_ids,
                semantic_blockers,
            ]
        )[:20]
        request_id = f"formal_blocker_resource_request:{fingerprint}"
        rows.append(
            {
                "request_id": request_id,
                "request_fingerprint": fingerprint,
                "source": (
                    "critic_source_theorem_exact_semantic_definition_repair_feedback"
                ),
                "blocker_kind": blocker_kind,
                "failure_classification": failure,
                "trigger": trigger,
                "placeholder_symbol": placeholder_symbol,
                "proof_body_gate_status": gate,
                "runtime_queue_status": runtime_queue_status,
                "environment_repair_status": environment_repair_status,
                "candidate_lean_project_hint": candidate_lean_project_hint,
                "candidate_source_file": candidate_source_file,
                "unavailable_module_prefix": unavailable_module_prefix,
                "recommended_next_action": recommended_next_action,
                "recommended_commands": recommended_commands,
                "blocker": blocker,
                "next_owner": "TheoryDeveloper/Formalizer/ProofEngineer/LeanProver",
                "target_ids": target_ids,
                "candidate_artifact_path": candidate_path,
                "semantic_alignment_blockers": semantic_blockers,
                "verified_adapter_context_ids": adapter_ids[:5],
                "formal_source_queries": _formal_blocker_resource_request_queries(
                    blocker,
                    blocker_kind=blocker_kind,
                    target_ids=target_ids,
                ),
                "recommended_tools": [
                    "formal_source_retriever",
                    "proof_search",
                    "lean_lsp_mcp_when_configured",
                    "local_lean_or_axle",
                ],
                "required_resolution": (
                    "Repair the selected Lean project/source-root/import-prefix "
                    "mapping for this exact semantic definition before retrying "
                    "proof-body tactics. A verified adapter may be consumed as "
                    "context, but source-theorem proof evidence requires local "
                    "Lean/AXLE verification of the exact declaration."
                    if environment_repair_status
                    else (
                        "Resolve the exact source-theorem semantic definitions and "
                        "target provenance before retrying proof-body tactics. A verified "
                        "adapter may be consumed as context, but source-theorem proof "
                        "evidence requires local Lean/AXLE verification of the exact "
                        "declaration."
                    )
                ),
                "proof_evidence_status": (
                    "FORMAL_BLOCKER_RESOURCE_REQUEST_NOT_PROOF_EVIDENCE"
                ),
                "proof_evidence_boundary": KERNEL_PROOF_BOUNDARY,
            }
        )
    return rows


def _formal_blocker_resource_requests_from_feedback(
    feedback: Mapping[str, Any] | None,
) -> list[dict[str, Any]]:
    """Carry prior typed blocker requests across repair loops."""

    if not isinstance(feedback, Mapping):
        return []
    return _merge_formal_blocker_resource_requests(
        [
            row
            for row in feedback.get("formal_blocker_resource_requests", []) or []
            if isinstance(row, Mapping)
        ]
    )


def _formal_blocker_target_ids_from_manifest_and_diagnostics(
    manifest: Mapping[str, Any],
    diagnostics: Sequence[Mapping[str, Any]],
) -> list[str]:
    question = (
        manifest.get("question", {})
        if isinstance(manifest.get("question", {}), Mapping)
        else {}
    )
    explicit_target_ids = list(
        dict.fromkeys(
            target_id
            for source_row in (manifest, *diagnostics)
            if isinstance(source_row, Mapping)
            for target_id in _source_theorem_explicit_target_ids_from_row(source_row)
        )
    )
    deterministic_goal_ids = [
        str(row.get("id", "") or "").strip()
        for row in manifest.get("deterministic_theorem_goals", []) or []
        if isinstance(row, Mapping) and str(row.get("id", "") or "").strip()
    ]
    diagnostic_target_names = [
        str(row.get("target_lean_declaration", "") or "").strip()
        for row in diagnostics
        if isinstance(row, Mapping)
        and str(row.get("target_lean_declaration", "") or "").strip()
    ]
    question_target_ids = [
        str(question.get("id", "") or "").strip()
    ] if str(question.get("id", "") or "").strip() else []
    return list(
        dict.fromkeys(
            explicit_target_ids
            or deterministic_goal_ids
            or diagnostic_target_names
            or question_target_ids
        )
    )


def _formal_blocker_resource_requests_from_unknown_identifiers(
    *,
    local_lean_repair_contract: Mapping[str, Any],
    manifest: Mapping[str, Any],
    diagnostics: Sequence[Mapping[str, Any]],
) -> list[dict[str, Any]]:
    """Convert local Lean unknown identifiers into typed prover/RAG requests."""

    if not isinstance(local_lean_repair_contract, Mapping):
        return []
    target_ids = _formal_blocker_target_ids_from_manifest_and_diagnostics(
        manifest,
        diagnostics,
    )
    rows: list[dict[str, Any]] = []
    source_manifest_id = str(manifest.get("manifest_id", "") or "")
    for unknown in local_lean_repair_contract.get("unknown_identifiers", []) or []:
        identifier = str(unknown).strip()
        if not identifier:
            continue
        blocker = (
            f"{identifier} unknown identifier in configured Lean project during "
            "local Lean repair; do not reuse it without a verified local declaration "
            "or smaller primitive."
        )
        fingerprint = stable_hash(
            [
                "formalizer_lean_candidate_local_lean_feedback",
                "lean_unknown_identifier",
                identifier,
                source_manifest_id,
            ]
        )[:20]
        rows.append(
            {
                "request_id": f"formal_blocker_resource_request:{fingerprint}",
                "source": "formalizer_lean_candidate_local_lean_feedback",
                "blocker_kind": "lean_unknown_identifier",
                "blocker": blocker,
                "next_owner": "ProofEngineer",
                "target_ids": target_ids,
                "formal_source_queries": _formal_blocker_resource_request_queries(
                    blocker,
                    blocker_kind="lean_unknown_identifier",
                    target_ids=target_ids,
                ),
                "recommended_tools": [
                    "formal_source_retriever",
                    "proof_search",
                    "lean_lsp_mcp_when_configured",
                    "local_lean_or_axle",
                ],
                "required_resolution": (
                    "Retrieve or identify a verified local declaration/import, "
                    "derive the needed fact from known primitives, or keep the "
                    "affected theorem as FORMAL_GAP with the exact unknown identifier "
                    "named. Do not emit an executable candidate that reuses the "
                    "unknown identifier."
                ),
                "proof_evidence_status": (
                    "FORMAL_BLOCKER_RESOURCE_REQUEST_NOT_PROOF_EVIDENCE"
                ),
                "proof_evidence_boundary": KERNEL_PROOF_BOUNDARY,
            }
        )
    return rows


def _formal_blocker_resource_requests_from_unavailable_imports(
    *,
    local_lean_repair_contract: Mapping[str, Any],
    manifest: Mapping[str, Any],
    diagnostics: Sequence[Mapping[str, Any]],
    source: str = "formalizer_lean_candidate_local_lean_feedback",
) -> list[dict[str, Any]]:
    """Convert unavailable Lean imports into typed prover/RAG requests."""

    if not isinstance(local_lean_repair_contract, Mapping):
        return []
    diagnostic_classes = {
        str(value)
        for value in local_lean_repair_contract.get("diagnostic_classes", []) or []
        if str(value).strip()
    }
    if "lean_import_environment_missing" not in diagnostic_classes:
        return []
    target_ids = _formal_blocker_target_ids_from_manifest_and_diagnostics(
        manifest,
        diagnostics,
    )
    replacements = [
        row
        for row in local_lean_repair_contract.get(
            "suggested_import_replacements", []
        )
        or []
        if isinstance(row, Mapping)
    ]
    blocked_modules = [
        str(value).strip()
        for value in local_lean_repair_contract.get("blocked_import_prefixes", []) or []
        if str(value).strip()
    ]
    for row in replacements:
        module = str(row.get("unavailable_module", "") or "").strip()
        if module:
            blocked_modules.append(module)
    blocked_modules = list(dict.fromkeys(blocked_modules))
    if not blocked_modules and local_lean_repair_contract.get(
        "mathlib_root_import_unavailable", False
    ):
        blocked_modules = ["Mathlib"]
    rows: list[dict[str, Any]] = []
    source_manifest_id = str(manifest.get("manifest_id", "") or "")
    source_label = str(source or "formalizer_lean_candidate_local_lean_feedback")
    for module in blocked_modules:
        replacement = next(
            (
                row
                for row in replacements
                if str(row.get("unavailable_module", "") or "").strip() == module
            ),
            {},
        )
        suggested_modules = [
            str(value).strip()
            for value in (
                replacement.get("suggested_modules", [])
                if isinstance(replacement, Mapping)
                else []
            )
            or []
            if str(value).strip()
        ]
        blocker = (
            f"{module} unavailable import in configured Lean project during "
            "candidate precheck/local Lean repair."
        )
        if suggested_modules:
            blocker += " Suggested replacement module(s): " + ", ".join(
                suggested_modules[:4]
            )
            blocker += ". Use a suggested module only if it provides the intended dependency."
        else:
            blocker += " Use a verified local import or fail closed with a dependency FORMAL_GAP."
        fingerprint = stable_hash(
            [
                source_label,
                "lean_unavailable_import",
                module,
                suggested_modules,
                source_manifest_id,
            ]
        )[:20]
        formal_source_queries = _formal_blocker_resource_request_queries(
            blocker,
            blocker_kind="lean_unavailable_import",
            target_ids=target_ids,
        )
        for value in [module, *suggested_modules]:
            query = f"{value} Lean import"
            if query not in formal_source_queries:
                formal_source_queries.append(query)
        rows.append(
            {
                "request_id": f"formal_blocker_resource_request:{fingerprint}",
                "source": source_label,
                "blocker_kind": "lean_unavailable_import",
                "blocker": blocker,
                "next_owner": "ProofEngineer",
                "target_ids": target_ids,
                "unavailable_import": module,
                "suggested_import_replacements": suggested_modules,
                "formal_source_queries": formal_source_queries[:5],
                "recommended_tools": [
                    "formal_source_retriever",
                    "lean_lsp_mcp_when_configured",
                    "local_lean_or_axle",
                ],
                "required_resolution": (
                    "Replace the unavailable import with a verified import in the "
                    "configured Lake project, remove the guessed import if unused, "
                    "or keep the affected theorem as FORMAL_GAP with the exact "
                    "missing dependency named. Do not emit an executable candidate "
                    "that repeats the unavailable import."
                ),
                "proof_evidence_status": (
                    "FORMAL_BLOCKER_RESOURCE_REQUEST_NOT_PROOF_EVIDENCE"
                ),
                "proof_evidence_boundary": KERNEL_PROOF_BOUNDARY,
            }
        )
    return rows


def _formal_blocker_resource_requests_from_repeated_syntax_failures(
    feedback: Mapping[str, Any],
) -> list[dict[str, Any]]:
    """Convert repeated parser failures into typed non-proof prover work."""

    if not isinstance(feedback, Mapping):
        return []
    contract = (
        feedback.get("local_lean_repair_contract", {})
        if isinstance(feedback.get("local_lean_repair_contract", {}), Mapping)
        else {}
    )
    if not contract.get("repeated_syntax_failure", False):
        return []
    diagnostics = [
        row
        for row in feedback.get("candidate_diagnostics", []) or []
        if isinstance(row, Mapping)
    ]
    target_ids: list[str] = []
    for row in diagnostics[:5]:
        for key in ("target_lean_declaration", "candidate_id"):
            value = str(row.get(key, "") or "").strip()
            if value and value not in target_ids:
                target_ids.append(value)
    diagnostic_excerpts = [
        str(
            row.get("local_lean_stdout_excerpt", "")
            or row.get("local_lean_stderr_excerpt", "")
            or ""
        ).strip()
        for row in diagnostics[:3]
        if str(
            row.get("local_lean_stdout_excerpt", "")
            or row.get("local_lean_stderr_excerpt", "")
            or ""
        ).strip()
    ]
    target_text = ", ".join(target_ids[:4]) or "materialized Lean candidate"
    blocker = (
        "Repeated Lean parser/syntax failure after a Formalizer repair retry for "
        f"{target_text}. Do not retry the same Unicode/complex theorem statement; "
        "fail closed to FORMAL_GAP or produce one minimal ASCII/core Lean support "
        "lemma in a support channel and rerun local Lean."
    )
    if diagnostic_excerpts:
        blocker += " Latest diagnostic excerpt: " + diagnostic_excerpts[0][:320]
    request_id = (
        "formal_blocker_resource_request:"
        + stable_hash(
            [
                "formalizer_lean_candidate_local_lean_feedback",
                "lean_repeated_parser_or_syntax_failure",
                target_ids,
                feedback.get("source_manifest_id", ""),
            ]
        )[:20]
    )
    formal_source_queries = _formal_blocker_resource_request_queries(
        blocker,
        blocker_kind="lean_repeated_parser_or_syntax_failure",
        target_ids=target_ids,
    )
    for query in (
        "Lean theorem syntax ASCII binder local declaration",
        "Lean parser unexpected token expected term theorem statement",
        "minimal core Lean Prop support lemma",
    ):
        if query not in formal_source_queries:
            formal_source_queries.append(query)
    return [
        {
            "request_id": request_id,
            "source": "formalizer_lean_candidate_local_lean_feedback",
            "blocker_kind": "lean_repeated_parser_or_syntax_failure",
            "blocker": blocker,
            "next_owner": "ProofEngineer",
            "target_ids": target_ids,
            "formal_source_queries": formal_source_queries[:5],
            "recommended_tools": [
                "local_lean_or_axle",
                "lean_lsp_mcp_when_configured",
                "formal_source_retriever",
                "proof_search",
            ],
            "required_resolution": (
                "Produce a syntactically valid minimal ASCII/core Lean helper and "
                "rerun local Lean, or keep the source theorem as FORMAL_GAP with "
                "the exact parser blocker named. Do not emit another executable "
                "candidate that repeats the same parser-failing theorem shape."
            ),
            "proof_evidence_status": (
                "FORMAL_BLOCKER_RESOURCE_REQUEST_NOT_PROOF_EVIDENCE"
            ),
            "proof_evidence_boundary": KERNEL_PROOF_BOUNDARY,
        }
    ]


def _exact_semantic_formal_blocker_request_key(
    row: Mapping[str, Any],
) -> tuple[str, tuple[str, ...]] | None:
    if (
        str(row.get("source", "") or "")
        != "critic_source_theorem_exact_semantic_definition_repair_feedback"
    ):
        return None
    placeholder_symbol = str(row.get("placeholder_symbol", "") or "").strip()
    if not placeholder_symbol:
        return None
    target_ids = tuple(
        str(value).strip()
        for value in row.get("target_ids", []) or []
        if str(value).strip()
    )
    return (placeholder_symbol, target_ids)


def _exact_semantic_formal_blocker_requests_overlap(
    existing: Mapping[str, Any],
    candidate: Mapping[str, Any],
) -> bool:
    existing_key = _exact_semantic_formal_blocker_request_key(existing)
    candidate_key = _exact_semantic_formal_blocker_request_key(candidate)
    if existing_key is None or candidate_key is None:
        return False
    existing_placeholder, existing_targets = existing_key
    candidate_placeholder, candidate_targets = candidate_key
    if existing_placeholder != candidate_placeholder:
        return False
    return (
        existing_targets == candidate_targets
        or not existing_targets
        or not candidate_targets
    )


def _exact_semantic_formal_blocker_request_is_stronger(
    existing: Mapping[str, Any],
    candidate: Mapping[str, Any],
) -> bool:
    existing_score = _exact_semantic_environment_repair_evidence_score(existing)
    candidate_score = _exact_semantic_environment_repair_evidence_score(candidate)
    if candidate_score != existing_score:
        return candidate_score > existing_score
    existing_key = _exact_semantic_formal_blocker_request_key(existing)
    candidate_key = _exact_semantic_formal_blocker_request_key(candidate)
    existing_targets = existing_key[1] if existing_key is not None else ()
    candidate_targets = candidate_key[1] if candidate_key is not None else ()
    return bool(candidate_targets) and not existing_targets


def _dedupe_exact_semantic_formal_blocker_resource_requests(
    requests: Sequence[Mapping[str, Any]],
) -> list[dict[str, Any]]:
    rows = [dict(row) for row in requests if isinstance(row, Mapping)]
    retained: list[dict[str, Any]] = []
    for row in rows:
        if _exact_semantic_formal_blocker_request_key(row) is None:
            retained.append(row)
            continue
        existing_index = next(
            (
                index
                for index, existing in enumerate(retained)
                if _exact_semantic_formal_blocker_requests_overlap(existing, row)
            ),
            None,
        )
        if existing_index is None:
            retained.append(row)
            continue
        existing = retained[existing_index]
        if _exact_semantic_formal_blocker_request_is_stronger(existing, row):
            retained[existing_index] = row
    return retained


def _merge_formal_blocker_resource_requests(
    *request_groups: Sequence[Mapping[str, Any]],
) -> list[dict[str, Any]]:
    """Normalize, fill defaults, and deduplicate formal blocker requests."""

    merged: list[dict[str, Any]] = []
    seen: set[str] = set()
    for group in request_groups:
        for row in group or []:
            if not isinstance(row, Mapping):
                continue
            blocker = str(row.get("blocker", "") or "").strip()
            blocker_kind = str(row.get("blocker_kind", "") or "").strip()
            request_id = str(row.get("request_id", "") or "").strip()
            if not blocker and not request_id:
                continue
            source = str(row.get("source", "") or "").strip() or "formal_blocker"
            next_owner = (
                str(row.get("next_owner", "") or "").strip()
                or "Formalizer/ProofEngineer"
            )
            target_ids = [
                str(value).strip()
                for value in row.get("target_ids", []) or []
                if str(value).strip()
            ]
            if not blocker_kind:
                blocker_kind = "formal_blocker"
            if not request_id:
                request_id = (
                    "formal_blocker_resource_request:"
                    + stable_hash([source, blocker_kind, blocker, next_owner])[:20]
                )
            fingerprint = stable_hash([request_id, source, blocker_kind, blocker])[:20]
            if fingerprint in seen:
                continue
            seen.add(fingerprint)
            formal_source_queries = [
                str(query).strip()
                for query in row.get("formal_source_queries", []) or []
                if str(query).strip()
            ]
            if not formal_source_queries and blocker:
                formal_source_queries = _formal_blocker_resource_request_queries(
                    blocker,
                    blocker_kind=blocker_kind,
                    target_ids=target_ids,
                )
            recommended_tools = [
                str(tool).strip()
                for tool in row.get("recommended_tools", []) or []
                if str(tool).strip()
            ]
            if not recommended_tools:
                recommended_tools = [
                    "formal_source_retriever",
                    "proof_search",
                    "lean_lsp_mcp_when_configured",
                    "local_lean_or_axle",
                ]
            merged.append(
                {
                    **dict(row),
                    "request_id": request_id,
                    "source": source,
                    "blocker_kind": blocker_kind,
                    "blocker": blocker,
                    "next_owner": next_owner,
                    "target_ids": target_ids,
                    "formal_source_queries": formal_source_queries[:5],
                    "recommended_tools": list(dict.fromkeys(recommended_tools)),
                    "required_resolution": str(
                        row.get("required_resolution", "") or ""
                    )
                    or (
                        "Retrieve or identify a verified local declaration/import, "
                        "formalize a smaller semantic primitive, or keep the theorem "
                        "as FORMAL_GAP with the exact missing resource named."
                    ),
                    "proof_evidence_status": (
                        "FORMAL_BLOCKER_RESOURCE_REQUEST_NOT_PROOF_EVIDENCE"
                    ),
                    "proof_evidence_boundary": KERNEL_PROOF_BOUNDARY,
                }
            )
            if len(merged) >= FORMAL_BLOCKER_RESOURCE_REQUEST_LIMIT:
                return _dedupe_exact_semantic_formal_blocker_resource_requests(merged)
    return _dedupe_exact_semantic_formal_blocker_resource_requests(merged)


def _critic_candidate_diagnostics_from_formalization_manifest(
    formalization_manifest: Mapping[str, Any],
) -> list[dict[str, Any]]:
    diagnostics: list[dict[str, Any]] = []
    if not isinstance(formalization_manifest, Mapping):
        return diagnostics
    formal_subclaims = formalization_manifest.get("formal_subclaims", []) or []
    if not isinstance(formal_subclaims, list | tuple):
        return diagnostics
    for row in formal_subclaims[:8]:
        if not isinstance(row, Mapping):
            continue
        errors = [str(error) for error in row.get("errors", []) or [] if str(error)]
        if not errors:
            continue
        diagnostics.append(
            {
                "candidate_id": str(row.get("id", "") or ""),
                "candidate_kind": str(row.get("claim_type", "") or ""),
                "source_field": "formal_subclaims",
                "precheck_status": str(row.get("status", "") or ""),
                "precheck_errors": [],
                "local_lean_attempted": True,
                "local_lean_compiled": bool(row.get("kernel_verified", False)),
                "local_lean_exit_status": (
                    "0" if bool(row.get("kernel_verified", False)) else "1"
                ),
                "local_lean_stdout_excerpt": "\n".join(errors[:3]),
            }
        )
    return diagnostics


def _critic_local_lean_repair_contract_from_formalization_manifest(
    formalization_manifest: Mapping[str, Any],
) -> dict[str, Any]:
    diagnostics = _critic_candidate_diagnostics_from_formalization_manifest(
        formalization_manifest
    )
    return _formalizer_local_lean_repair_contract_from_diagnostics(diagnostics)


def _compact_agenda_item(row: Mapping[str, Any]) -> dict[str, Any]:
    compact = {
        "id": str(row.get("id", "")),
        "owner_subsystem": str(row.get("owner_subsystem", "")),
        "trigger": str(row.get("trigger", "")),
        "action": str(row.get("action", "")),
        "acceptance_gate": str(row.get("acceptance_gate", "")),
        "priority": str(row.get("priority", "")),
    }
    for key in (
        "target_ids",
        "runtime_queue_status",
        "source_to_bridge_metadata_blocker_status",
        "source_to_bridge_metadata_blocker_kind",
        "diagnostic_helper_candidate_ids",
        "source_formalizer_packet_id",
        "recommended_formalizer_target_mode",
        "failure_classifications",
        "proof_body_gate_statuses",
        "semantic_alignment_blockers",
    ):
        if key in row:
            compact[key] = row.get(key)
    return compact


def _compact_formal_subclaim_feedback(row: Mapping[str, Any]) -> dict[str, Any]:
    return {
        "id": str(row.get("id", "")),
        "claim_type": str(row.get("claim_type", "")),
        "status": str(row.get("status", "")),
        "kernel_verified": bool(row.get("kernel_verified", False)),
        "gap_reason": str(row.get("gap_reason", "")),
        "errors": list(row.get("errors", []) or [])[:3],
        "proof_dependencies": list(row.get("proof_dependencies", []) or [])[:5],
    }


def _architect_runtime_plan(context: Mapping[str, Any]) -> dict[str, Any]:
    plan = context.get("architect_runtime_plan")
    if isinstance(plan, Mapping):
        return dict(plan)
    contract = context.get("runtime_requested_evidence_contract")
    if isinstance(contract, Mapping) and contract:
        return {
            "subsystem_execution_plan": [],
            "evidence_contract": dict(contract),
            "evidence_gates": [
                {
                    "artifact_kind": "runtime requested evidence contract",
                    "required_evidence": (
                        "follow formal_verification_policy and "
                        "recommended_research_path until an Architect packet "
                        "overrides them"
                    ),
                    "not_evidence": (
                        "requested policy/path is orchestration control, not "
                        "proof, simulation, or implementation evidence"
                    ),
                }
            ],
            "boundary": (
                "Runtime requested evidence contract is orchestration control "
                "metadata. It does not prove or validate any statistical claim "
                "and must not replace live Architect reasoning in capability "
                "evaluations."
            ),
        }
    return {}


def _architect_subsystem_plan(context: Mapping[str, Any], subsystem: str) -> dict[str, Any]:
    plan = _architect_runtime_plan(context)
    for row in plan.get("subsystem_execution_plan", []) or []:
        if not isinstance(row, Mapping):
            continue
        if str(row.get("subsystem", "")).strip() == subsystem:
            return dict(row)
    return {}


def _architect_acceptance_gate(
    context: Mapping[str, Any],
    subsystem: str,
    default: str,
) -> str:
    row = _architect_subsystem_plan(context, subsystem)
    gate = str(row.get("acceptance_gate", "")).strip()
    return gate or default


def _architect_expected_artifacts(
    context: Mapping[str, Any],
    subsystem: str,
    default: tuple[str, ...],
) -> tuple[str, ...]:
    row = _architect_subsystem_plan(context, subsystem)
    artifacts = [
        str(item).strip()
        for item in row.get("expected_artifacts", []) or []
        if str(item).strip()
    ]
    return tuple(artifacts) if artifacts else default


def _architect_control_payload(context: Mapping[str, Any], subsystem: str) -> dict[str, Any]:
    plan = _architect_runtime_plan(context)
    row = _architect_subsystem_plan(context, subsystem)
    if not plan and not row:
        return {}
    evidence_gates = [
        dict(item)
        for item in plan.get("evidence_gates", []) or []
        if isinstance(item, Mapping)
    ]
    iteration_policy = plan.get("iteration_policy", {})
    retrieval_strategy = plan.get("retrieval_strategy", {})
    problem_analysis = plan.get("problem_analysis", {})
    knowledge_bank_plan = plan.get("stat_knowledge_bank_plan", {})
    fair_comparison_plan = plan.get("literature_fair_comparison_plan", [])
    evidence_contract = plan.get("evidence_contract", {})
    if not isinstance(evidence_contract, Mapping):
        evidence_contract = {}
    return {
        "architect_coordinator_proposal_id": str(
            context.get("architect_coordinator_proposal_id", "")
        ),
        "subsystem": subsystem,
        "subsystem_plan": row,
        "acceptance_gate": str(row.get("acceptance_gate", "")).strip(),
        "expected_artifacts": [
            str(item).strip()
            for item in row.get("expected_artifacts", []) or []
            if str(item).strip()
        ],
        "evidence_gates": evidence_gates,
        "iteration_policy": dict(iteration_policy) if isinstance(iteration_policy, Mapping) else {},
        "retrieval_strategy": dict(retrieval_strategy) if isinstance(retrieval_strategy, Mapping) else {},
        "problem_analysis": dict(problem_analysis) if isinstance(problem_analysis, Mapping) else {},
        "stat_knowledge_bank_plan": dict(knowledge_bank_plan) if isinstance(knowledge_bank_plan, Mapping) else {},
        "literature_fair_comparison_plan": [
            dict(item) for item in fair_comparison_plan if isinstance(item, Mapping)
        ],
        "evidence_contract": dict(evidence_contract),
        "formal_verification_policy": str(
            evidence_contract.get("formal_verification_policy", "") or ""
        ),
        "recommended_research_path": str(
            evidence_contract.get("recommended_research_path", "") or ""
        ),
        "formal_required_for_final": bool(
            evidence_contract.get("formal_required_for_final", False)
        ),
        "boundary": str(plan.get("boundary", "")),
    }


def _runtime_environment_feedback_with_architect_directive(
    *,
    context: Mapping[str, Any],
    subsystem: str,
    feedback: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    payload = dict(feedback) if isinstance(feedback, Mapping) else {}
    runtime_task = context.get("runtime_task", {})
    if isinstance(runtime_task, Mapping) and runtime_task:
        payload.setdefault("runtime_task", dict(runtime_task))
    requested_contract = context.get("runtime_requested_evidence_contract", {})
    if isinstance(requested_contract, Mapping) and requested_contract:
        payload.setdefault("runtime_requested_evidence_contract", dict(requested_contract))
    control = _architect_control_payload(context, subsystem)
    if not control:
        return payload
    evidence_contract = control.get("evidence_contract", {})
    if isinstance(evidence_contract, Mapping) and evidence_contract:
        payload.setdefault("architect_evidence_contract", dict(evidence_contract))
    for key in (
        "formal_verification_policy",
        "recommended_research_path",
        "formal_required_for_final",
    ):
        if control.get(key) not in (None, "", [], {}):
            payload.setdefault(f"architect_{key}", control.get(key))
    if control.get("acceptance_gate"):
        payload.setdefault(
            "architect_subsystem_acceptance_gate",
            str(control.get("acceptance_gate", "")),
        )
    return payload


def _runtime_algorithm_sandbox_feedback_from_learning_memory(
    architect_context: Mapping[str, Any],
    question_id: str,
) -> dict[str, Any]:
    return _runtime_feedback_from_learning_memory(
        architect_context,
        question_id,
        learning_task="algorithm_sandbox_execution_feedback",
        feedback_type="algorithm_sandbox_execution_feedback",
    )


def _runtime_generated_simulation_feedback_from_learning_memory(
    architect_context: Mapping[str, Any],
    question_id: str,
) -> dict[str, Any]:
    return _runtime_feedback_from_learning_memory(
        architect_context,
        question_id,
        learning_task="generated_simulation_sandbox_execution_feedback",
        feedback_type="generated_simulation_sandbox_execution_feedback",
    )


def _runtime_feedback_from_learning_memory(
    architect_context: Mapping[str, Any],
    question_id: str,
    *,
    learning_task: str,
    feedback_type: str,
) -> dict[str, Any]:
    memory = (
        architect_context.get("runtime_learning_memory", {})
        if isinstance(architect_context, Mapping)
        else {}
    )
    if (
        not isinstance(memory, Mapping)
        or memory.get("artifact_kind") != "RuntimeLearningMemoryContext"
    ):
        return {}
    rows = memory.get("rows", []) if isinstance(memory.get("rows"), list) else []
    for row in reversed(rows):
        if not isinstance(row, Mapping):
            continue
        if str(row.get("learning_task", "") or "") != learning_task:
            continue
        row_question_id = str(row.get("question_id", "") or "")
        if row_question_id and question_id and row_question_id != question_id:
            continue
        feedback = dict(row)
        feedback["feedback_type"] = str(row.get("feedback_type", "") or feedback_type)
        feedback.setdefault(
            "boundary",
            (
                "Runtime learning memory is repair guidance from prior local "
                "execution. It is not proof evidence or a claim that the code "
                "currently passes."
            ),
        )
        return feedback
    return {}


def _runtime_context_contract_flag(
    context: Mapping[str, Any],
    *,
    subsystem: str,
    flag: str,
) -> bool:
    requested_contract = context.get("runtime_requested_evidence_contract", {})
    if isinstance(requested_contract, Mapping) and requested_contract.get(flag) is True:
        return True
    control = _architect_control_payload(context, subsystem)
    evidence_contract = control.get("evidence_contract", {})
    return bool(
        isinstance(evidence_contract, Mapping)
        and evidence_contract.get(flag) is True
    )


def _runtime_requires_generated_algorithm_code(
    context: Mapping[str, Any],
) -> bool:
    return _runtime_context_contract_flag(
        context,
        subsystem="AlgorithmEngineer",
        flag="capability_eval_requires_generated_algorithm_code",
    )


def _runtime_requires_generated_simulation_code(
    context: Mapping[str, Any],
) -> bool:
    return _runtime_context_contract_flag(
        context,
        subsystem="SimulationEvaluator",
        flag="capability_eval_requires_generated_simulation_code",
    )


def _latest_artifact(blackboard: BlackboardState, prefix: str) -> dict[str, Any]:
    for key in reversed(list(blackboard.artifacts.keys())):
        if key.startswith(prefix) and isinstance(blackboard.artifacts[key], dict):
            return dict(blackboard.artifacts[key])
    return {}


def _algorithm_proposal_for_estimator(
    proposal_packet: Mapping[str, Any] | None,
    estimator_id: str,
) -> dict[str, Any]:
    if not isinstance(proposal_packet, Mapping):
        return {}
    for row in proposal_packet.get("implementation_targets", []) or []:
        if not isinstance(row, Mapping):
            continue
        if str(row.get("estimator_id", "")) == estimator_id:
            return dict(row)
    return {}


def _algorithm_code_draft_for_estimator(
    proposal_packet: Mapping[str, Any] | None,
    estimator_id: str,
) -> dict[str, Any]:
    if not isinstance(proposal_packet, Mapping):
        return {}
    for row in proposal_packet.get("sandbox_code_drafts", []) or []:
        if not isinstance(row, Mapping):
            continue
        if str(row.get("estimator_id", "")) == estimator_id:
            return dict(row)
    return {}


def _registered_algorithm_template_hint(
    *,
    proposal_target: Mapping[str, Any],
    spec: Mapping[str, Any],
    question: OpenResearchQuestion,
) -> str:
    explicit = str(proposal_target.get("registered_template_hint", "") or "").strip()
    if explicit == "none":
        return ""
    if explicit in {"crossfit_aipw", "split_conformal_interval"}:
        return explicit
    haystack = " ".join(
        str(part)
        for part in (
            explicit,
            spec.get("id", ""),
            spec.get("name", ""),
            spec.get("algorithm_sketch", ""),
            spec.get("formula", ""),
            question.id,
            question.title,
            question.description,
            " ".join(question.tags),
        )
    ).lower()
    if "crossfit" in haystack or "aipw" in haystack:
        return "crossfit_aipw"
    if "conformal" in haystack and (
        "interval" in haystack
        or "prediction" in haystack
        or "coverage" in haystack
    ):
        return "split_conformal_interval"
    return ""


def _formalization_manifest_source_to_bridge_metadata_blocker(
    formalization_manifest: Mapping[str, Any],
) -> dict[str, Any]:
    if not isinstance(formalization_manifest, Mapping):
        return {}
    proof_bank_memory_summary = (
        formalization_manifest.get("proof_bank_runtime_memory_summary", {})
        if isinstance(
            formalization_manifest.get("proof_bank_runtime_memory_summary", {}),
            Mapping,
        )
        else {}
    )
    target_mode = str(
        proof_bank_memory_summary.get("recommended_formalizer_target_mode", "")
        or ""
    ).strip()
    diagnostic_helper_bridge_mode = (
        target_mode == "source_theorem_diagnostic_helper_bridge_or_blocker"
        or bool(
            proof_bank_memory_summary.get(
                "formalizer_diagnostic_helper_integration_required",
                False,
            )
        )
    )
    helper_rows = [
        dict(row)
        for row in proof_bank_memory_summary.get(
            "formalizer_diagnostic_helper_memory",
            [],
        )
        or []
        if isinstance(row, Mapping)
    ]
    helper_candidate_ids = [
        str(row.get("candidate_id", "") or "").strip()
        for row in helper_rows
        if str(row.get("candidate_id", "") or "").strip()
    ]
    gap_rows: list[dict[str, Any]] = []
    for key in ("llm_formalizer_gap_taxonomy", "gap_taxonomy"):
        raw_rows = formalization_manifest.get(key, [])
        if isinstance(raw_rows, list | tuple):
            gap_rows.extend(dict(row) for row in raw_rows if isinstance(row, Mapping))
    blocker_gap_rows: list[dict[str, str]] = []
    for row in gap_rows:
        gap = str(row.get("gap", "") or "").strip()
        kind = str(row.get("kind", "") or "").strip()
        next_owner = str(row.get("next_owner", "") or "").strip()
        text = f"{kind} {gap} {next_owner}".lower()
        if (
            kind == "source_to_bridge_metadata_blocker"
            or (
                "source-binding" in text
                and "source_to_bridge_premise_derivation" in text
            )
            or (
                "source-to-bridge" in text
                and "metadata" in text
                and "semantic anchor" in text
            )
        ):
            blocker_gap_rows.append(
                {
                    "gap": gap,
                    "kind": kind or "source_to_bridge_metadata_blocker",
                    "next_owner": next_owner,
                }
            )
    blocker_status = str(
        formalization_manifest.get(
            "llm_formalizer_diagnostic_helper_bridge_blocker_status",
            "",
        )
        or formalization_manifest.get("diagnostic_helper_bridge_blocker_status", "")
        or ""
    ).strip()
    candidate_rows = [
        dict(row)
        for row in formalization_manifest.get(
            "llm_formalizer_source_to_bridge_premise_derivation_candidates",
            [],
        )
        or []
        if isinstance(row, Mapping)
    ]
    work_order_rows = [
        dict(row)
        for row in formalization_manifest.get(
            "source_to_bridge_premise_derivation_work_orders",
            [],
        )
        or []
        if isinstance(row, Mapping)
    ]
    diagnostics = [
        dict(row)
        for row in proof_bank_memory_summary.get(
            "source_to_bridge_premise_derivation_diagnostics",
            [],
        )
        or []
        if isinstance(row, Mapping)
    ]
    has_source_to_bridge_candidate_request = bool(candidate_rows or work_order_rows)
    if not has_source_to_bridge_candidate_request:
        for row in diagnostics:
            if (
                str(
                    row.get(
                        "source_to_bridge_premise_derivation_candidate_request_id",
                        "",
                    )
                    or ""
                ).strip()
                or isinstance(
                    row.get("source_to_bridge_premise_derivation_candidate_request"),
                    Mapping,
                )
                or str(
                    row.get(
                        "source_to_bridge_grouped_premise_derivation_candidate_request_id",
                        "",
                    )
                    or ""
                ).strip()
                or isinstance(
                    row.get(
                        "source_to_bridge_grouped_premise_derivation_candidate_request"
                    ),
                    Mapping,
                )
            ):
                has_source_to_bridge_candidate_request = True
                break
    inferred_from_helper_memory = (
        diagnostic_helper_bridge_mode
        and bool(helper_rows)
        and not has_source_to_bridge_candidate_request
    )
    if not (blocker_status or blocker_gap_rows or inferred_from_helper_memory):
        return {}
    target_ids = [
        str(value).strip()
        for value in proof_bank_memory_summary.get("remaining_theorem_goal_ids", [])
        or []
        if str(value).strip()
    ]
    if not target_ids:
        target_ids = [
            str(row.get("id", "") or "").strip()
            for row in formalization_manifest.get("deterministic_theorem_goals", [])
            or []
            if isinstance(row, Mapping) and str(row.get("id", "") or "").strip()
        ]
    return {
        "status": (
            blocker_status
            or "SOURCE_TO_BRIDGE_METADATA_BLOCKER_INFERRED_FROM_DIAGNOSTIC_HELPER_MEMORY"
        ),
        "recommended_formalizer_target_mode": target_mode,
        "target_ids": target_ids,
        "diagnostic_helper_candidate_ids": list(dict.fromkeys(helper_candidate_ids)),
        "blocker_gaps": blocker_gap_rows[:5],
        "source_formalizer_packet_id": str(
            formalization_manifest.get(
                "llm_formalizer_proof_engineer_proposal_id",
                "",
            )
            or ""
        ),
        "formalization_manifest_id": str(
            formalization_manifest.get("manifest_id", "") or ""
        ),
    }


def _source_to_bridge_metadata_blocker_agenda_item(
    *,
    blocker: Mapping[str, Any],
    fallback_target_ids: list[str],
) -> dict[str, Any]:
    target_ids = [
        str(value).strip()
        for value in blocker.get("target_ids", []) or []
        if str(value).strip()
    ] or [value for value in fallback_target_ids if value]
    helper_ids = [
        str(value).strip()
        for value in blocker.get("diagnostic_helper_candidate_ids", []) or []
        if str(value).strip()
    ]
    return {
        "id": "formal_gap:source_to_bridge_metadata_authoring",
        "owner_subsystem": "TheoryDeveloper/SourceBindingMetadata/Formalizer",
        "trigger": "SOURCE_TO_BRIDGE_METADATA_BLOCKER",
        "action": (
            "author or retrieve exact source-to-bridge premise-derivation "
            "candidate request metadata: premise names, exact source theorem "
            "binders, adapter object names requiring source instantiation, "
            "semantic anchor binders, and required anchor references before "
            "asking Formalizer for executable "
            "source_to_bridge_premise_derivation_candidates"
        ),
        "acceptance_gate": (
            "proof_bank_runtime_memory_summary exposes a "
            "source_to_bridge_premise_derivation_candidate_request or "
            "source_to_bridge_grouped_premise_derivation_candidate_request "
            "with source-binding metadata, exact_source_theorem_binders, "
            "premise_semantic_anchor_binders, and "
            "required_semantic_anchor_reference_names"
        ),
        "target_ids": target_ids,
        "diagnostic_helper_candidate_ids": helper_ids,
        "source_to_bridge_metadata_blocker_status": str(
            blocker.get("status", "") or ""
        ),
        "source_to_bridge_metadata_blocker_kind": (
            "source_to_bridge_metadata_blocker"
        ),
        "source_formalizer_packet_id": str(
            blocker.get("source_formalizer_packet_id", "") or ""
        ),
        "formalization_manifest_id": str(
            blocker.get("formalization_manifest_id", "") or ""
        ),
        "recommended_formalizer_target_mode": str(
            blocker.get("recommended_formalizer_target_mode", "") or ""
        ),
        "blocker_gaps": [
            dict(row)
            for row in blocker.get("blocker_gaps", []) or []
            if isinstance(row, Mapping)
        ],
        "runtime_queue_status": "PENDING_SOURCE_TO_BRIDGE_METADATA_AUTHORING",
        "priority": "high",
        "proof_boundary": KERNEL_PROOF_BOUNDARY,
        "boundary": (
            "Source-to-bridge metadata authoring is orchestration context only. "
            "It can unblock a later premise-derivation candidate request, but it "
            "is not theorem proof evidence and does not certify any helper as "
            "source-theorem proof."
        ),
    }


def _source_theorem_exact_semantic_definition_repair_agenda_item(
    *,
    proof_bank_memory_summary: Mapping[str, Any],
    fallback_target_ids: list[str],
) -> dict[str, Any]:
    target_ids = [
        str(value).strip()
        for value in proof_bank_memory_summary.get(
            "source_theorem_exact_candidate_repair_target_names",
            [],
        )
        or []
        if str(value).strip()
    ] or [value for value in fallback_target_ids if value]
    failure_classifications = [
        str(value).strip()
        for value in proof_bank_memory_summary.get(
            "source_theorem_exact_candidate_failure_classifications",
            [],
        )
        or []
        if str(value).strip()
    ]
    triggers = [
        str(value).strip()
        for value in proof_bank_memory_summary.get(
            "source_theorem_exact_candidate_repair_triggers",
            [],
        )
        or []
        if str(value).strip()
    ]
    diagnostics = [
        row
        for row in proof_bank_memory_summary.get(
            "source_theorem_exact_candidate_repair_diagnostics",
            [],
        )
        or []
        if isinstance(row, Mapping)
    ]
    proof_body_gate_statuses = list(
        dict.fromkeys(
            str(row.get("proof_body_gate_status", "") or "").strip()
            for row in diagnostics
            if str(row.get("proof_body_gate_status", "") or "").strip()
        )
    )
    if not proof_body_gate_statuses and any(
        failure in _SOURCE_THEOREM_EXACT_SEMANTIC_REPAIR_FAILURES
        for failure in failure_classifications
    ):
        proof_body_gate_statuses = ["SEMANTIC_REVIEW_REQUIRED_BEFORE_PROOF_BODY"]
    semantic_alignment_blockers = list(
        dict.fromkeys(
            str(value).strip()
            for row in diagnostics
            for value in row.get("semantic_alignment_blockers", []) or []
            if str(value).strip()
        )
    )
    return {
        "id": "formal_gap:source_theorem_exact_semantic_definition_repair",
        "owner_subsystem": "TheoryDeveloper/Formalizer/ProofEngineer/LeanProver",
        "trigger": "SOURCE_THEOREM_EXACT_SEMANTIC_DEFINITION_REVIEW_REQUIRED",
        "action": (
            "review, retrieve, import, or formalize exact source-theorem semantic "
            "definitions before retrying the exact proof body"
        ),
        "acceptance_gate": (
            "proof_bank_runtime_memory_summary records reviewed or kernel-verified "
            "exact semantic definitions, then local Lean/AXLE reruns the exact "
            "source theorem proof body; verified adapter rows remain context only"
        ),
        "target_ids": list(dict.fromkeys(target_ids)),
        "failure_classifications": list(dict.fromkeys(failure_classifications)),
        "source_theorem_exact_candidate_repair_triggers": list(
            dict.fromkeys(triggers)
        ),
        "proof_body_gate_statuses": proof_body_gate_statuses,
        "semantic_alignment_blockers": semantic_alignment_blockers[:8],
        "recommended_formalizer_target_mode": (
            _SOURCE_THEOREM_EXACT_SEMANTIC_REPAIR_MODE
        ),
        "runtime_queue_status": _SOURCE_THEOREM_EXACT_SEMANTIC_REPAIR_QUEUE_STATUS,
        "priority": "high",
        "proof_boundary": KERNEL_PROOF_BOUNDARY,
        "boundary": (
            "Exact semantic-definition review is orchestration and repair guidance, "
            "not proof evidence. Source-theorem proof evidence requires local "
            "Lean/AXLE verification of the exact theorem declaration."
        ),
    }


def _critic_next_action_agenda(
    *,
    question: OpenResearchQuestion,
    retrieval_manifest: Mapping[str, Any],
    theory_packet: Mapping[str, Any],
    simulation_manifest: Mapping[str, Any],
    algorithm_manifest: Mapping[str, Any],
    formalization_manifest: Mapping[str, Any],
) -> list[dict[str, Any]]:
    agenda: list[dict[str, Any]] = []
    formal_counts = formalization_manifest.get("counts", {}) if isinstance(formalization_manifest, Mapping) else {}
    proof_bank_memory_summary = (
        formalization_manifest.get("proof_bank_runtime_memory_summary", {})
        if isinstance(
            formalization_manifest.get("proof_bank_runtime_memory_summary", {}),
            Mapping,
        )
        else {}
    )
    source_to_bridge_metadata_blocker = (
        _formalization_manifest_source_to_bridge_metadata_blocker(
            formalization_manifest
        )
    )
    if int(formal_counts.get("formal_gap", 0) or 0) > 0:
        gap_goals = [
            row.get("id", "")
            for row in formalization_manifest.get("deterministic_theorem_goals", []) or []
            if isinstance(row, Mapping)
        ]
        exact_semantic_definition_repair_required = bool(
            proof_bank_memory_summary.get(
                "source_theorem_exact_semantic_definition_repair_required",
                False,
            )
            or str(
                proof_bank_memory_summary.get(
                    "recommended_formalizer_target_mode",
                    "",
                )
                or ""
            )
            == _SOURCE_THEOREM_EXACT_SEMANTIC_REPAIR_MODE
        )
        source_theorem_candidate_materialization_required = bool(
            proof_bank_memory_summary.get(
                "source_theorem_candidate_materialization_required",
                False,
            )
            or str(
                proof_bank_memory_summary.get(
                    "recommended_formalizer_target_mode",
                    "",
                )
                or ""
            )
            == "source_theorem_exact_candidate_materialization_required"
        )
        if source_theorem_candidate_materialization_required:
            materialization_statuses = [
                str(value).strip()
                for value in proof_bank_memory_summary.get(
                    "source_theorem_candidate_materialization_required_statuses",
                    [],
                )
                or []
                if str(value).strip()
            ]
            materialization_contract = str(
                proof_bank_memory_summary.get(
                    "source_theorem_candidate_materialization_contract",
                    "",
                )
                or ""
            ).strip()
            agenda.append(
                {
                    "id": "formal_gap:source_theorem_candidate_materialization",
                    "owner_subsystem": (
                        "Formalizer/ProofEngineer/AgenticMaterializer/LeanProver"
                    ),
                    "trigger": (
                        "EXACT_SOURCE_THEOREM_CANDIDATE_MATERIALIZATION_REQUIRED"
                    ),
                    "action": (
                        "materialize a runnable exact source-theorem Lean candidate "
                        "artifact, then run signature probes to obtain the live "
                        "proof-body location before exact proof-body execution"
                    ),
                    "acceptance_gate": materialization_contract
                    or (
                        "A concrete exact source-theorem Lean candidate artifact, "
                        "signature_probe_artifact_path, target Lean declaration, "
                        "and live proof-body location are available; proof evidence "
                        "still requires later local Lean/AXLE kernel verification."
                    ),
                    "target_ids": list(
                        proof_bank_memory_summary.get(
                            "source_theorem_candidate_materialization_required_target_names",
                            [],
                        )
                        or []
                    )
                    or [row for row in gap_goals if row],
                    "candidate_materialization_statuses": materialization_statuses,
                    "failure_classifications": list(
                        proof_bank_memory_summary.get(
                            "source_theorem_exact_candidate_failure_classifications",
                            [],
                        )
                        or []
                    ),
                    "recommended_formalizer_target_mode": (
                        "source_theorem_exact_candidate_materialization_required"
                    ),
                    "runtime_queue_status": (
                        "PENDING_EXACT_SOURCE_THEOREM_CANDIDATE_MATERIALIZATION"
                    ),
                    "priority": "high",
                    "proof_boundary": KERNEL_PROOF_BOUNDARY,
                    "boundary": (
                        "Candidate materialization is operational routing context, "
                        "not proof evidence. The materialized artifact must still "
                        "pass local Lean/AXLE before any source-theorem proof claim."
                    ),
                }
            )
        if proof_bank_memory_summary.get(
            "source_theorem_exact_candidate_environment_gap", False
        ) and not source_theorem_candidate_materialization_required:
            agenda.append(
                {
                    "id": "formal_gap:source_theorem_formal_environment_repair",
                    "owner_subsystem": "Formalizer/ProofEngineer/LeanProver",
                    "trigger": "SOURCE_THEOREM_EXACT_CANDIDATE_FORMAL_ENVIRONMENT_GAP",
                    "action": (
                        "repair the exact source-theorem candidate formal environment: "
                        "identify the required Lean project, imports, source theorem "
                        "module, and missing statistical primitives before attempting "
                        "proof-body tactics"
                    ),
                    "acceptance_gate": (
                        "local Lean/AXLE reaches the exact source theorem declaration "
                        "with imports and symbols resolved; proof evidence still requires "
                        "artifact_kernel_verified/source_theorem_kernel_verified"
                    ),
                    "target_ids": list(
                        proof_bank_memory_summary.get(
                            "source_theorem_exact_candidate_repair_target_names",
                            [],
                        )
                        or []
                    )
                    or [row for row in gap_goals if row],
                    "failure_classifications": list(
                        proof_bank_memory_summary.get(
                            "source_theorem_exact_candidate_failure_classifications",
                            [],
                        )
                        or []
                    ),
                    "priority": "high",
                    "proof_boundary": KERNEL_PROOF_BOUNDARY,
                }
            )
        if exact_semantic_definition_repair_required:
            agenda.append(
                _source_theorem_exact_semantic_definition_repair_agenda_item(
                    proof_bank_memory_summary=proof_bank_memory_summary,
                    fallback_target_ids=[row for row in gap_goals if row],
                )
            )
        elif source_to_bridge_metadata_blocker:
            agenda.append(
                _source_to_bridge_metadata_blocker_agenda_item(
                    blocker=source_to_bridge_metadata_blocker,
                    fallback_target_ids=[row for row in gap_goals if row],
                )
            )
        elif proof_bank_memory_summary.get(
            "source_to_bridge_premise_derivation_required", False
        ):
            premise_names = [
                str(value).strip()
                for value in proof_bank_memory_summary.get(
                    "source_to_bridge_premise_derivation_pending_premise_names",
                    [],
                )
                or []
                if str(value).strip()
            ]
            premise_targets = [
                str(row.get("premise_target_type", "") or "").strip()
                for row in proof_bank_memory_summary.get(
                    "source_to_bridge_premise_derivation_diagnostics",
                    [],
                )
                or []
                if isinstance(row, Mapping)
                and str(row.get("premise_target_type", "") or "").strip()
            ]
            agenda.append(
                {
                    "id": "formal_gap:source_to_bridge_premise_derivation",
                    "owner_subsystem": "TheoryDeveloper/Formalizer/ProofEngineer",
                    "trigger": "SOURCE_TO_BRIDGE_PREMISE_DERIVATION_GAP",
                    "action": (
                        "derive the concrete source-to-bridge premises from exact "
                        "source-theorem hypotheses, or revise the source theorem "
                        "semantic assumptions/lemma plan before rerunning the adapter "
                        "or exact source theorem proof body"
                    ),
                    "acceptance_gate": (
                        "AXLE/local Lean verifies non-vacuous premise derivations "
                        "for the listed bridge premises; full source theorem proof "
                        "still requires a later exact source theorem kernel check"
                    ),
                    "target_ids": [row for row in gap_goals if row],
                    "premise_names": premise_names,
                    "premise_target_types": premise_targets,
                    "priority": "high",
                    "proof_boundary": KERNEL_PROOF_BOUNDARY,
                }
            )
        elif _formalization_manifest_has_remaining_proof_bank_work(formalization_manifest):
            agenda.append(
                {
                    "id": "formal_gap:proof_bank_expansion",
                    "owner_subsystem": "Formalizer/LeanProver",
                    "trigger": "FORMAL_GAP",
                    "action": "promote retrieved formal-source hits into reusable Lean proof-bank obligations",
                    "acceptance_gate": "AXLE/local Lean kernel verifies the new obligation and full theorem gaps remain explicit",
                    "target_ids": [row for row in gap_goals if row],
                    "priority": "high",
                    "proof_boundary": KERNEL_PROOF_BOUNDARY,
                }
            )
        elif _formalization_manifest_has_kernel_verified_theorem_closure(
            formalization_manifest
        ) and _formalization_manifest_has_kernel_verified_source_semantic_support(
            formalization_manifest
        ):
            agenda.append(
                {
                    "id": "formal_gap:source_theorem_exact_semantics_or_promotion",
                    "owner_subsystem": "TheoryDeveloper/Formalizer/LeanProver",
                    "trigger": "FORMAL_GAP_AFTER_KERNEL_VERIFIED_CLOSURE_AND_SEMANTIC_BRIDGE_SUPPORT",
                    "action": (
                        "target exact upstream statistical semantic definitions or source-theorem "
                        "promotion, while preserving the distinction between verified registered "
                        "semantic bridges and the full source theorem"
                    ),
                    "acceptance_gate": (
                        "AXLE/local Lean kernel verifies exact upstream semantic primitives or "
                        "the full source theorem; registered bridge evidence remains separately scoped"
                    ),
                    "target_ids": [row for row in gap_goals if row],
                    "priority": "high",
                    "proof_boundary": KERNEL_PROOF_BOUNDARY,
                }
            )
        elif _formalization_manifest_has_kernel_verified_theorem_closure(
            formalization_manifest
        ):
            agenda.append(
                {
                    "id": "formal_gap:source_theorem_semantic_primitives",
                    "owner_subsystem": "TheoryDeveloper/Formalizer/LeanProver",
                    "trigger": "FORMAL_GAP_AFTER_KERNEL_VERIFIED_THEOREM_REDUCTION_CLOSURE",
                    "action": (
                        "formalize the upstream statistical semantics needed by the source theorem, "
                        "such as exchangeability-to-uniform-rank and order-statistic quantile construction"
                    ),
                    "acceptance_gate": (
                        "AXLE/local Lean kernel verifies each upstream primitive, and the manifest "
                        "keeps theorem-reduction closure evidence separate from full source theorem proof"
                    ),
                    "target_ids": [row for row in gap_goals if row],
                    "priority": "high",
                    "proof_boundary": KERNEL_PROOF_BOUNDARY,
                }
            )
        else:
            agenda.append(
                {
                    "id": "formal_gap:theorem_reduction_closure",
                    "owner_subsystem": "Formalizer/LeanProver",
                    "trigger": "FORMAL_GAP_WITH_PROOF_BANK_EXHAUSTED",
                    "action": (
                        "formalize the theorem-level reduction that connects the "
                        "kernel-verified proof-bank subclaims to the frontier theorem statement"
                    ),
                    "acceptance_gate": (
                        "AXLE/local Lean kernel verifies the theorem-level reduction, "
                        "or the manifest records a precise semantic/source theorem blocker"
                    ),
                    "target_ids": [row for row in gap_goals if row],
                    "priority": "high",
                    "proof_boundary": KERNEL_PROOF_BOUNDARY,
                }
            )
        if str(formalization_manifest.get("formalization_gap_planner_bridge_id", "")).strip():
            agenda.append(
                {
                    "id": "formal_gap:gap_planner_handoff",
                    "owner_subsystem": "FormalizationGapPlanner",
                    "trigger": "FORMAL_GAP_WITH_RUNTIME_GAP_PLANNER_SEED",
                    "action": (
                        "stage the LLM route-planner prompt packets from the "
                        "runtime standalone seed, then run the standalone "
                        "minimal-delta planner before expanding broad theory"
                    ),
                    "acceptance_gate": (
                        "LLM route plan, standalone gap plan, source grounding "
                        "audit, and target-prover replay preserve proof boundaries"
                    ),
                    "formalization_gap_planner_bridge_id": str(
                        formalization_manifest.get(
                            "formalization_gap_planner_bridge_id",
                            "",
                        )
                    ),
                    "standalone_seed_artifact_id": str(
                        formalization_manifest.get(
                            "formalization_gap_planner_standalone_seed_artifact_id",
                            "",
                        )
                    ),
                    "target_ids": [row for row in gap_goals if row],
                    "priority": "high",
                    "proof_boundary": (
                        RUNTIME_FORMALIZATION_GAP_PLANNER_BRIDGE_BOUNDARY
                    ),
                }
            )
    if int(formal_counts.get("kernel_verified", 0) or 0) == 0 and int(formal_counts.get("proved", 0) or 0) > 0:
        agenda.append(
            {
                "id": "proof_feedback:kernel_rerun",
                "owner_subsystem": "FormalizationEvaluator",
                "trigger": "NONKERNEL_PROOF_ROWS",
                "action": "rerun registered proof-bank rows with --local-lean or --real-lean before claiming kernel evidence",
                "acceptance_gate": "kernel_verified count is recorded from AXLE/local Lean",
                "priority": "high",
                "proof_boundary": KERNEL_PROOF_BOUNDARY,
            }
        )
    if isinstance(algorithm_manifest, Mapping) and int(algorithm_manifest.get("n_executed", 0) or 0) > 0:
        agenda.append(
            {
                "id": "algorithm:prototype_review",
                "owner_subsystem": "AlgorithmEngineer",
                "trigger": "SANDBOX_PROTOTYPE_EXECUTED",
                "action": "review sandbox prototype and, if appropriate, promote through registered algorithm audit",
                "acceptance_gate": "production implementation hash, registry entry, tests, and simulation rerun pass",
                "target_ids": [
                    row.get("estimator_id", "")
                    for row in algorithm_manifest.get("prototypes", []) or []
                    if isinstance(row, Mapping)
                ],
                "priority": "medium",
                "boundary": algorithm_manifest.get("boundary", ""),
            }
        )
    if isinstance(simulation_manifest, Mapping) and simulation_manifest.get("simulation_passed") is not True:
        agenda.append(
            {
                "id": "simulation:theory_revision",
                "owner_subsystem": "TheoryDeveloper",
                "trigger": "SIMULATION_DIAGNOSTIC_FAILURE",
                "action": "revise theorem/procedure using failed simulation diagnostics",
                "acceptance_gate": "rerun simulation passes or blocker is classified",
                "priority": "high",
                "boundary": SIMULATION_NOT_PROOF_BOUNDARY,
            }
        )
    retrieval_counts = retrieval_manifest.get("counts", {}) if isinstance(retrieval_manifest, Mapping) else {}
    if int(retrieval_counts.get("formal_source_hits", 0) or 0) == 0:
        agenda.append(
            {
                "id": "retrieval:expand_formal_sources",
                "owner_subsystem": "RetrievalMemory",
                "trigger": "NO_FORMAL_SOURCE_HITS",
                "action": "expand Lean/Mathlib/StatInference/OpenProver search context for this theorem family",
                "acceptance_gate": "retrieval manifest records formal-source hits or an explicit source-authority gap",
                "priority": "medium",
                "boundary": retrieval_manifest.get("boundary", ""),
            }
        )
    if not agenda:
        agenda.append(
            {
                "id": "monitor:runtime_trace",
                "owner_subsystem": "CriticEvaluator",
                "trigger": "NO_BLOCKING_RUNTIME_GAPS",
                "action": "archive runtime trace or expand benchmark stress tests",
                "acceptance_gate": "evidence ledger boundaries remain intact",
                "priority": "low",
            }
        )
    for row in agenda:
        row["question_id"] = question.id
        row["theory_packet_id"] = str(theory_packet.get("packet_id", ""))
    return _dedupe_runtime_next_action_agenda_rows(agenda)


def _formalization_manifest_has_remaining_proof_bank_work(
    formalization_manifest: Mapping[str, Any],
) -> bool:
    proof_control = (
        formalization_manifest.get("proof_obligation_control", {})
        if isinstance(formalization_manifest.get("proof_obligation_control"), Mapping)
        else {}
    )
    if not proof_control:
        return True
    for key in (
        "deferred_priority_proof_obligation_ids_due_to_max",
        "deferred_proof_obligation_ids_due_to_max",
        "requested_non_candidate_proof_obligation_ids",
    ):
        if any(str(row).strip() for row in proof_control.get(key, []) or []):
            return True
    formal_subclaims = (
        formalization_manifest.get("formal_subclaims", [])
        if isinstance(formalization_manifest.get("formal_subclaims", []), list)
        else []
    )
    for row in formal_subclaims:
        if not isinstance(row, Mapping):
            continue
        if str(row.get("claim_type", "")) != "lean_obligation":
            continue
        if row.get("status") == "FAILED":
            return True
        if row.get("status") == "PROVED" and row.get("kernel_verified") is not True:
            return True
    candidate_ids = {
        str(row).strip()
        for row in proof_control.get("candidate_proof_obligation_ids", []) or []
        if str(row).strip()
    }
    if not candidate_ids:
        return False
    kernel_verified_ids = {
        str(row.get("proof_obligation_id", "")).strip()
        for row in formal_subclaims
        if isinstance(row, Mapping)
        and row.get("kernel_verified") is True
        and str(row.get("proof_obligation_id", "")).strip()
    }
    kernel_verified_ids |= {
        str(row).strip()
        for row in proof_control.get("memory_kernel_verified_proof_obligation_ids", []) or []
        if str(row).strip()
    }
    kernel_verified_ids |= {
        str(row).strip()
        for row in proof_control.get("excluded_candidate_proof_obligation_ids", []) or []
        if str(row).strip()
    }
    return bool(candidate_ids - kernel_verified_ids)


def _formalization_manifest_has_kernel_verified_theorem_closure(
    formalization_manifest: Mapping[str, Any],
) -> bool:
    proof_control = (
        formalization_manifest.get("proof_obligation_control", {})
        if isinstance(formalization_manifest.get("proof_obligation_control"), Mapping)
        else {}
    )
    if proof_control.get("theorem_reduction_closure_already_kernel_verified") is True:
        return True
    summary = (
        formalization_manifest.get("proof_bank_runtime_memory_summary", {})
        if isinstance(
            formalization_manifest.get("proof_bank_runtime_memory_summary"),
            Mapping,
        )
        else {}
    )
    return summary.get("theorem_reduction_closure_already_kernel_verified") is True


