def _runtime_learning_memory_kernel_verified_theorem_reduction_closure(
    architect_context: Mapping[str, Any],
) -> dict[str, tuple[str, ...]]:
    memory = (
        architect_context.get("runtime_learning_memory", {})
        if isinstance(architect_context, Mapping)
        else {}
    )
    if (
        not isinstance(memory, Mapping)
        or memory.get("artifact_kind") != "RuntimeLearningMemoryContext"
    ):
        return {
            "work_order_ids": (),
            "target_ids": (),
            "declarations": (),
            "artifact_paths": (),
            "signature_excerpts": (),
            "goal_ids": (),
        }
    rows = memory.get("rows", []) if isinstance(memory.get("rows"), list) else []
    work_order_ids: list[str] = []
    target_ids: list[str] = []
    declarations: list[str] = []
    artifact_paths: list[str] = []
    signature_excerpts: list[str] = []
    goal_ids: list[str] = []
    for row in rows:
        if not isinstance(row, Mapping):
            continue
        for key, bucket in (
            ("kernel_verified_theorem_reduction_closure_work_order_ids", work_order_ids),
            ("kernel_verified_theorem_reduction_closure_target_ids", target_ids),
            ("kernel_verified_theorem_reduction_closure_declarations", declarations),
            ("verified_theorem_reduction_closure_artifact_paths", artifact_paths),
            (
                "kernel_verified_theorem_reduction_closure_signature_excerpts",
                signature_excerpts,
            ),
            ("kernel_verified_theorem_reduction_closure_goal_ids", goal_ids),
        ):
            for value in row.get(key, []) or []:
                text = str(value).strip()
                if text:
                    bucket.append(text)
        input_summary = row.get("input_summary", {})
        if isinstance(input_summary, Mapping):
            for key, bucket in (
                ("kernel_verified_theorem_reduction_closure_work_order_ids", work_order_ids),
                ("kernel_verified_theorem_reduction_closure_target_ids", target_ids),
                ("kernel_verified_theorem_reduction_closure_declarations", declarations),
                ("verified_theorem_reduction_closure_artifact_paths", artifact_paths),
                (
                    "kernel_verified_theorem_reduction_closure_signature_excerpts",
                    signature_excerpts,
                ),
                ("kernel_verified_theorem_reduction_closure_goal_ids", goal_ids),
            ):
                for value in input_summary.get(key, []) or []:
                    text = str(value).strip()
                    if text:
                        bucket.append(text)
    if not signature_excerpts and artifact_paths:
        signature_excerpts.extend(
            _lean_declaration_signature_excerpts_from_artifacts(
                artifact_paths=artifact_paths,
                declarations=declarations,
            )
        )
    return {
        "work_order_ids": tuple(dict.fromkeys(work_order_ids)),
        "target_ids": tuple(dict.fromkeys(target_ids)),
        "declarations": tuple(dict.fromkeys(declarations)),
        "artifact_paths": tuple(dict.fromkeys(artifact_paths)),
        "signature_excerpts": tuple(dict.fromkeys(signature_excerpts)),
        "goal_ids": tuple(dict.fromkeys(goal_ids)),
    }


def _lean_declaration_signature_excerpts_from_artifacts(
    *,
    artifact_paths: list[str],
    declarations: list[str],
    max_artifacts: int = 3,
) -> list[str]:
    excerpts: list[str] = []
    for index, artifact_path in enumerate(artifact_paths[:max_artifacts]):
        declaration = declarations[index] if index < len(declarations) else ""
        excerpt = _lean_declaration_signature_excerpt_from_artifact_path(
            artifact_path,
            declaration=declaration,
        )
        if excerpt and excerpt not in excerpts:
            excerpts.append(excerpt)
    return excerpts


def _lean_declaration_signature_excerpt_from_artifact_path(
    artifact_path: str,
    *,
    declaration: str = "",
    max_lines: int = 40,
    max_chars: int = 2000,
) -> str:
    path_text = str(artifact_path or "").strip()
    if not path_text or not path_text.endswith(".lean"):
        return ""
    try:
        path = Path(path_text).expanduser()
        text = path.read_text(encoding="utf-8")
    except OSError:
        return ""
    wanted = str(declaration or "").strip()
    pattern = (
        rf"^\s*(?:noncomputable\s+)?(?:private\s+)?(?:theorem|lemma|def|abbrev)\s+"
        rf"{re.escape(wanted)}\b"
        if wanted
        else r"^\s*(?:noncomputable\s+)?(?:private\s+)?(?:theorem|lemma|def|abbrev)\s+"
    )
    lines = text.splitlines()
    start = -1
    for index, line in enumerate(lines):
        if re.search(pattern, line):
            start = index
            break
    if start < 0:
        return ""
    excerpt_lines: list[str] = []
    for line in lines[start : start + max_lines]:
        if ":=" in line:
            before, _sep, _after = line.partition(":=")
            excerpt_lines.append(before.rstrip())
            break
        excerpt_lines.append(line.rstrip())
    return "\n".join(excerpt_lines).strip()[:max_chars]


