def _runtime_row_string_values(
    row: Mapping[str, Any],
    *keys: str,
) -> tuple[str, ...]:
    values: list[str] = []
    sources: list[Mapping[str, Any]] = [row]
    input_summary = row.get("input_summary", {})
    if isinstance(input_summary, Mapping):
        sources.append(input_summary)
    for source in sources:
        for key in keys:
            raw = source.get(key)
            if isinstance(raw, list | tuple | set):
                candidates = raw
            else:
                candidates = [raw]
            for value in candidates:
                text = str(value or "").strip()
                if text:
                    values.append(text)
    return tuple(dict.fromkeys(values))


def _runtime_row_nested_string_values(
    row: Mapping[str, Any],
    *keys: str,
) -> tuple[str, ...]:
    values: list[str] = []
    sources: list[Mapping[str, Any]] = [row]
    input_summary = row.get("input_summary", {})
    if isinstance(input_summary, Mapping):
        sources.append(input_summary)
    for source in tuple(sources):
        candidate_request = source.get(
            "source_to_bridge_premise_derivation_candidate_request",
            {},
        )
        if isinstance(candidate_request, Mapping):
            sources.append(candidate_request)
        grouped_candidate_request = source.get(
            "source_to_bridge_grouped_premise_derivation_candidate_request",
            {},
        )
        if isinstance(grouped_candidate_request, Mapping):
            sources.append(grouped_candidate_request)
    for source in sources:
        for key in keys:
            raw = source.get(key)
            candidates = raw if isinstance(raw, list | tuple | set) else [raw]
            for value in candidates:
                text = str(value or "").strip()
                if text:
                    values.append(text)
    return tuple(dict.fromkeys(values))


def _runtime_row_mapping_values(
    row: Mapping[str, Any],
    *keys: str,
) -> tuple[dict[str, Any], ...]:
    values: list[dict[str, Any]] = []
    sources: list[Mapping[str, Any]] = [row]
    input_summary = row.get("input_summary", {})
    if isinstance(input_summary, Mapping):
        sources.append(input_summary)
    for source in tuple(sources):
        candidate_request = source.get(
            "source_to_bridge_premise_derivation_candidate_request",
            {},
        )
        if isinstance(candidate_request, Mapping):
            sources.append(candidate_request)
        grouped_candidate_request = source.get(
            "source_to_bridge_grouped_premise_derivation_candidate_request",
            {},
        )
        if isinstance(grouped_candidate_request, Mapping):
            sources.append(grouped_candidate_request)
    for source in sources:
        for key in keys:
            raw = source.get(key)
            candidates = raw if isinstance(raw, list | tuple) else [raw]
            for value in candidates:
                if isinstance(value, Mapping):
                    values.append(dict(value))
    seen: set[tuple[tuple[str, str], ...]] = set()
    deduped: list[dict[str, Any]] = []
    for value in values:
        fingerprint = tuple(
            sorted((str(key), str(nested)) for key, nested in value.items())
        )
        if fingerprint in seen:
            continue
        seen.add(fingerprint)
        deduped.append(value)
    return tuple(deduped)


def _proof_body_goal_excerpt_contains_goal(excerpt: Sequence[Any]) -> bool:
    return any("⊢" in str(value) for value in excerpt or [])


def _runtime_row_target_identity_keys(row: Mapping[str, Any]) -> tuple[str, ...]:
    values: list[str] = []
    sources: list[Mapping[str, Any]] = [row]
    input_summary = row.get("input_summary", {})
    if isinstance(input_summary, Mapping):
        sources.append(input_summary)
    for nested_key in (
        "source_theorem_target_provenance",
        "source_theorem_target_context",
        "kernel_overlay_context",
        "overlay_row",
    ):
        nested = row.get(nested_key, {})
        if isinstance(nested, Mapping):
            sources.append(nested)
    for source in sources:
        for key in (
            "target_theorem_name",
            "target_lean_declaration",
            "expected_target_lean_declaration",
        ):
            value = str(source.get(key, "") or "").strip()
            if value:
                values.append(value)
    source_formal_target_id = str(row.get("source_formal_target_id", "") or "").strip()
    if source_formal_target_id.startswith("target:"):
        values.append(source_formal_target_id.removeprefix("target:"))
    elif source_formal_target_id:
        values.append(source_formal_target_id)
    return tuple(dict.fromkeys(values))


def _exact_proof_body_goal_feedback_by_target(
    rows: Sequence[Mapping[str, Any]],
) -> dict[str, dict[str, Any]]:
    feedback_by_target: dict[str, dict[str, Any]] = {}
    for row in rows:
        excerpt = list(_runtime_row_string_values(row, "proof_body_goal_excerpt"))[:12]
        attempt_summaries = list(
            _runtime_row_string_values(row, "proof_body_attempt_summaries")
        )[:8]
        if not excerpt and not attempt_summaries:
            continue
        payload = {
            "proof_body_goal_excerpt": excerpt,
            "proof_body_attempt_summaries": attempt_summaries,
            "failure_classification": str(
                row.get("failure_classification", "") or ""
            ),
            "proof_body_gate_status": str(row.get("proof_body_gate_status", "") or ""),
            "proof_evidence_status": str(row.get("proof_evidence_status", "") or ""),
        }
        payload_has_goal = _proof_body_goal_excerpt_contains_goal(excerpt)
        for key in _runtime_row_target_identity_keys(row):
            existing = feedback_by_target.get(key)
            if existing is None:
                feedback_by_target[key] = payload
                continue
            existing_has_goal = _proof_body_goal_excerpt_contains_goal(
                existing.get("proof_body_goal_excerpt", [])
            )
            if payload_has_goal or not existing_has_goal:
                feedback_by_target[key] = payload
    return feedback_by_target


def _runtime_row_exact_proof_body_feedback(
    row: Mapping[str, Any],
    feedback_by_target: Mapping[str, Mapping[str, Any]],
) -> Mapping[str, Any]:
    for key in _runtime_row_target_identity_keys(row):
        feedback = feedback_by_target.get(key)
        if isinstance(feedback, Mapping):
            return feedback
    return {}


def _runtime_row_proof_body_goal_excerpt_with_exact_feedback(
    row: Mapping[str, Any],
    feedback_by_target: Mapping[str, Mapping[str, Any]],
    *,
    limit: int,
) -> list[str]:
    excerpt = list(_runtime_row_string_values(row, "proof_body_goal_excerpt"))[:limit]
    if _proof_body_goal_excerpt_contains_goal(excerpt):
        return excerpt
    feedback = _runtime_row_exact_proof_body_feedback(row, feedback_by_target)
    feedback_excerpt = [
        str(value)
        for value in feedback.get("proof_body_goal_excerpt", []) or []
        if str(value).strip()
    ][:limit]
    if _proof_body_goal_excerpt_contains_goal(feedback_excerpt):
        return feedback_excerpt
    return excerpt


def _runtime_row_proof_body_goal_excerpt_source(
    row: Mapping[str, Any],
    feedback_by_target: Mapping[str, Mapping[str, Any]],
) -> str:
    excerpt = list(_runtime_row_string_values(row, "proof_body_goal_excerpt"))[:12]
    if _proof_body_goal_excerpt_contains_goal(excerpt):
        return "row"
    feedback = _runtime_row_exact_proof_body_feedback(row, feedback_by_target)
    if _proof_body_goal_excerpt_contains_goal(
        feedback.get("proof_body_goal_excerpt", []) or []
    ):
        return "exact_source_theorem_proof_body_execution_feedback"
    return ""


def _runtime_row_proof_body_attempt_summaries_with_exact_feedback(
    row: Mapping[str, Any],
    feedback_by_target: Mapping[str, Mapping[str, Any]],
    *,
    limit: int,
) -> list[str]:
    attempt_summaries = list(
        _runtime_row_string_values(row, "proof_body_attempt_summaries")
    )[:limit]
    if attempt_summaries:
        return attempt_summaries
    feedback = _runtime_row_exact_proof_body_feedback(row, feedback_by_target)
    return [
        str(value)
        for value in feedback.get("proof_body_attempt_summaries", []) or []
        if str(value).strip()
    ][:limit]


def _source_theorem_target_provenance_from_row(row: Mapping[str, Any]) -> dict[str, Any]:
    sources: list[Mapping[str, Any]] = [row]
    for nested_key in (
        "source_theorem_target_provenance",
        "source_theorem_target_context",
        "kernel_overlay_context",
        "overlay_row",
    ):
        nested = row.get(nested_key, {})
        if isinstance(nested, Mapping):
            sources.append(nested)
    provenance: dict[str, Any] = {}
    if any("source_theorem_target_known" in source for source in sources):
        provenance["source_theorem_target_known"] = any(
            bool(source.get("source_theorem_target_known", False))
            for source in sources
        )
    constraints: list[str] = []
    for source in sources:
        for key in _SOURCE_THEOREM_TARGET_PROVENANCE_STRING_KEYS:
            if key in provenance:
                continue
            value = str(source.get(key, "") or "").strip()
            if value:
                provenance[key] = value
        constraints.extend(
            str(value).strip()
            for value in source.get("semantic_alignment_constraints", []) or []
            if str(value).strip()
        )
    if constraints:
        provenance["semantic_alignment_constraints"] = list(dict.fromkeys(constraints))
    return provenance


def _source_theorem_explicit_target_ids_from_row(row: Mapping[str, Any]) -> list[str]:
    sources: list[Mapping[str, Any]] = [row]
    for nested_key in (
        "source_theorem_target_provenance",
        "source_theorem_target_context",
        "kernel_overlay_context",
        "overlay_row",
        "input_summary",
    ):
        nested = row.get(nested_key, {})
        if isinstance(nested, Mapping):
            sources.append(nested)
    for source in tuple(sources):
        nested = source.get("source_theorem_target_provenance", {})
        if isinstance(nested, Mapping):
            sources.append(nested)

    target_ids: list[str] = []
    for source in sources:
        for key in ("target_ids", "target_id", "source_theorem_goal_id"):
            for value in _str_tuple(source.get(key, [])):
                text = str(value or "").strip()
                if text:
                    target_ids.append(text)
    return list(dict.fromkeys(target_ids))


def _source_theorem_target_ids_from_row(
    row: Mapping[str, Any],
    *,
    fallback_target_theorem_name: str = "",
    fallback_source_formal_target_id: str = "",
) -> list[str]:
    sources: list[Mapping[str, Any]] = [row]
    for nested_key in (
        "source_theorem_target_provenance",
        "source_theorem_target_context",
        "kernel_overlay_context",
        "overlay_row",
        "input_summary",
    ):
        nested = row.get(nested_key, {})
        if isinstance(nested, Mapping):
            sources.append(nested)
    for source in tuple(sources):
        nested = source.get("source_theorem_target_provenance", {})
        if isinstance(nested, Mapping):
            sources.append(nested)

    target_ids: list[str] = _source_theorem_explicit_target_ids_from_row(row)
    if not target_ids:
        for source in sources:
            for value in _str_tuple(source.get("target_theorem_goal_ids", [])):
                text = str(value or "").strip()
                if text:
                    target_ids.append(text)

    if not target_ids:
        for fallback in (
            fallback_target_theorem_name,
            fallback_source_formal_target_id,
        ):
            text = str(fallback or "").strip()
            if text:
                target_ids.append(text)
                break
    return list(dict.fromkeys(target_ids))


def _source_theorem_work_order_target_ids(
    row: Mapping[str, Any],
    *,
    source_target_provenance: Mapping[str, Any],
    fallback_target_theorem_name: str = "",
    fallback_source_formal_target_id: str = "",
) -> list[str]:
    target_row = dict(row)
    target_row["source_theorem_target_provenance"] = dict(source_target_provenance)
    return _source_theorem_target_ids_from_row(
        target_row,
        fallback_target_theorem_name=fallback_target_theorem_name,
        fallback_source_formal_target_id=fallback_source_formal_target_id,
    )


def _int_like(value: Any, default: int = 0) -> int:
    try:
        return int(value)
    except (TypeError, ValueError):
        return default


