def _source_theorem_placeholder_resolution_rows(
    repairs: tuple[dict[str, Any], ...],
) -> list[dict[str, Any]]:
    replacement_catalog = {
        "MeasureProbability": {
            "replacement_strategy": (
                "replace generated `MeasureProbability Ω` with "
                "`P : MeasureTheory.Measure Ω` and "
                "`[MeasureTheory.IsProbabilityMeasure P]`"
            ),
            "search_targets": [
                "MeasureTheory.Measure",
                "MeasureTheory.IsProbabilityMeasure",
                "Mathlib.MeasureTheory.Measure.ProbabilityMeasure",
            ],
            "promotion_gate": (
                "source theorem promotion remains blocked until the probability "
                "measure semantics are represented by reviewed Mathlib/StatInference "
                "declarations, not a local wrapper"
            ),
        },
        "Exchangeable": {
            "replacement_strategy": (
                "map generated `Exchangeable P s` to a reviewed exchangeability "
                "predicate over the joint law/permutation-invariant score family"
            ),
            "search_targets": [
                "exchangeable finite family",
                "permutation invariant distribution",
                "StatInference conformal exchangeability primitive",
            ],
            "promotion_gate": (
                "source theorem promotion remains blocked until exchangeability "
                "semantics are reviewed or kernel-proved as a source primitive"
            ),
        },
        "orderStatistic": {
            "replacement_strategy": (
                "replace generated `orderStatistic` with a reviewed finite "
                "order-statistic/quantile primitive compatible with calibration "
                "indices"
            ),
            "search_targets": [
                "finite order statistic real",
                "Finset sort nth",
                "StatInference conformal quantile primitive",
            ],
            "promotion_gate": (
                "source theorem promotion remains blocked until the order-statistic "
                "definition is tied to the rank/coverage bridge semantics"
            ),
        },
        "orderStat": {
            "replacement_strategy": (
                "replace generated `orderStat` with a reviewed finite "
                "order-statistic/quantile primitive compatible with calibration "
                "indices"
            ),
            "search_targets": [
                "finite order statistic real",
                "Finset sort nth",
                "StatInference conformal quantile primitive",
            ],
            "promotion_gate": (
                "source theorem promotion remains blocked until the order-statistic "
                "definition is tied to the rank/coverage bridge semantics"
            ),
        },
        "covered": {
            "replacement_strategy": (
                "instantiate the adapter object `covered` from the exact source "
                "coverage-event binder, normally the hypothesis hC tying C/q_hat "
                "to the event {y | score <= q_hat}"
            ),
            "search_targets": [
                "coverage event identity",
                "source theorem hC coverage set",
                "split conformal covered event",
            ],
            "promotion_gate": (
                "source theorem promotion remains blocked until `covered` is "
                "defined from exact source theorem binders rather than assumed "
                "as an adapter premise"
            ),
        },
    }
    rows: list[dict[str, Any]] = []
    seen: set[tuple[str, str]] = set()
    for repair in repairs:
        target = str(repair.get("target_theorem_name", "") or "")
        for symbol in repair.get("missing_formal_symbols", []) or []:
            symbol_value = str(symbol or "").strip()
            if not symbol_value:
                continue
            key = (target, symbol_value)
            if key in seen:
                continue
            seen.add(key)
            catalog_row = replacement_catalog.get(symbol_value, {})
            rows.append(
                {
                    "target_theorem_name": target,
                    "placeholder_symbol": symbol_value,
                    "failure_classification": str(
                        repair.get("failure_classification", "") or ""
                    ),
                    "replacement_strategy": str(
                        catalog_row.get(
                            "replacement_strategy",
                            "search Mathlib/StatInference/local Lean sources for a reviewed primitive before using a local placeholder",
                        )
                    ),
                    "search_targets": list(catalog_row.get("search_targets", [])),
                    "promotion_gate": str(
                        catalog_row.get(
                            "promotion_gate",
                            "placeholder primitives are routing evidence only and block source theorem promotion",
                        )
                    ),
                    "candidate_registered_obligation_ids": list(
                        _registered_support_for_placeholder_symbol(symbol_value)
                    ),
                    "proof_evidence_status": (
                        "PLACEHOLDER_RESOLUTION_PLAN_NOT_PROOF_EVIDENCE"
                    ),
                }
            )
    return rows


def _source_theorem_proof_body_adapter_required_reasons(
    repair: Mapping[str, Any],
) -> list[str]:
    """Detect proof-body failures that need a source-to-bridge adapter first."""

    trigger = str(repair.get("trigger", "") or "").strip()
    failure_classification = str(
        repair.get("failure_classification", "") or ""
    ).strip()
    runtime_queue_status = str(
        repair.get("runtime_queue_status", "") or ""
    ).strip()
    proof_body_gate_status = str(
        repair.get("proof_body_gate_status", "") or ""
    ).strip()
    reduction_closure_adapter_instantiation_missing = (
        failure_classification
        in _SOURCE_THEOREM_PROOF_BODY_ADAPTER_INSTANTIATION_FAILURES
        or runtime_queue_status
        in _SOURCE_THEOREM_PROOF_BODY_ADAPTER_INSTANTIATION_STATUSES
        or trigger in _SOURCE_THEOREM_PROOF_BODY_ADAPTER_INSTANTIATION_TRIGGERS
    )
    proof_dependency_context_missing = (
        failure_classification == "proof_body_dependency_context_missing"
    )
    if (
        failure_classification != "proof_body_incomplete"
        and not proof_dependency_context_missing
        and not reduction_closure_adapter_instantiation_missing
        and proof_body_gate_status != "PROOF_BODY_REACHED_PROOF_INCOMPLETE"
    ):
        return []
    if not bool(repair.get("proof_body_goal_reached", False)):
        return []

    goal_lines = [
        str(value)
        for value in (
            repair.get("proof_body_goal_excerpt", [])
            or repair.get("diagnostics", [])
            or []
        )
        if str(value).strip()
    ]
    goal_text = "\n".join(goal_lines)
    lower_goal = goal_text.lower()
    source_hypothesis_markers = (
        "hexch :",
        "hq :",
        "hc :",
        "exchangeable",
        "orderstat",
        "order statistic",
        "q_hat",
    )
    has_source_level_goal = any(
        marker in lower_goal for marker in source_hypothesis_markers
    )
    bridge_markers = (
        "split_conformal_finite_sample_coverage_reduction_closure",
        "good_rank",
        "bad_rank",
        "rank_uniform",
        "coverage_bridge",
        "bridge",
    )
    has_usable_bridge_hypothesis = any(
        marker in lower_goal for marker in bridge_markers
    )
    attempt_text = "\n".join(
        str(value)
        for value in repair.get("proof_body_attempt_summaries", []) or []
        if str(value).strip()
    ).lower()
    attempted_missing_bridge_dependency = (
        proof_dependency_context_missing
        or (
            (
                "diagnostic_kind=unknown_identifier" in attempt_text
                or "diagnostic_kind=unknown_constant" in attempt_text
                or "unknown identifier" in attempt_text
                or "unknown constant" in attempt_text
            )
            and any(marker in attempt_text for marker in bridge_markers)
        )
    )

    constraints = [
        str(value)
        for value in (
            repair.get("semantic_alignment_constraints", [])
            or repair.get("semantic_alignment_blockers", [])
            or []
        )
        if str(value).strip()
    ]
    constraints_text = "\n".join(constraints).lower()
    source_theorem_kernel_evidence_eligible = bool(
        repair.get("source_theorem_kernel_evidence_eligible", True)
    )
    semantic_or_review_gate_open = (
        not source_theorem_kernel_evidence_eligible
        or any(
            marker in constraints_text
            for marker in (
                "not eligible",
                "requires source review",
                "still requires source review",
                "tie",
                "indexing convention",
                "exchangeab",
                "order-statistic",
                "order statistic",
                "rank",
                "quantile",
                "bridge",
            )
        )
    )

    reasons: list[str] = []
    if reduction_closure_adapter_instantiation_missing:
        reasons.append(
            "verified reduction/closure theorem is available but cannot be instantiated from the exact source theorem hypotheses without a source-to-closure adapter"
        )
        reasons.append(
            "proof-body attempts failed while applying the verified reduction/closure theorem; derive the adapter instead of retrying the exact proof body unchanged"
        )
    if attempted_missing_bridge_dependency:
        reasons.append(
            "proof-body attempts referenced an unavailable bridge/reduction declaration"
        )
    if has_source_level_goal and not has_usable_bridge_hypothesis:
        reasons.append(
            "proof body goal exposes source-level hypotheses but no reusable bridge/reduction hypothesis"
        )
    if semantic_or_review_gate_open:
        reasons.append(
            "semantic alignment or evidence-eligibility gate is still open for the exact source theorem"
        )
    if attempted_missing_bridge_dependency:
        return reasons
    if len(reasons) < 2:
        return []
    return reasons


def _runtime_learning_memory_formalizer_lean_candidate_feedback(
    architect_context: Mapping[str, Any],
) -> tuple[dict[str, Any], ...]:
    """Return prior Formalizer candidate local-Lean diagnostics from memory."""

    memory = (
        architect_context.get("runtime_learning_memory", {})
        if isinstance(architect_context, Mapping)
        else {}
    )
    if (
        not isinstance(memory, Mapping)
        or memory.get("artifact_kind") != "RuntimeLearningMemoryContext"
    ):
        return ()
    rows = memory.get("rows", []) if isinstance(memory.get("rows"), list) else []
    feedback_rows: list[dict[str, Any]] = []
    seen: set[tuple[str, str, str]] = set()
    for row in rows:
        if not isinstance(row, Mapping):
            continue
        if str(row.get("learning_task", "") or "") != (
            "formalizer_lean_candidate_kernel_feedback"
        ):
            continue
        candidate_id = str(row.get("candidate_id", "") or "").strip()
        source_manifest_path = str(row.get("source_manifest_path", "") or "").strip()
        artifact_path = str(row.get("artifact_path", "") or "").strip()
        key = (candidate_id, source_manifest_path, artifact_path)
        if key in seen:
            continue
        seen.add(key)
        local_lean_attempted = bool(row.get("local_lean_attempted", False))
        local_lean_compiled = bool(row.get("local_lean_compiled", False))
        target_ids = _source_theorem_target_ids_from_row(
            row,
            fallback_target_theorem_name=str(
                row.get("target_theorem_name", "") or ""
            ),
            fallback_source_formal_target_id=str(
                row.get("target_lean_declaration", "") or ""
            ),
        )
        target_theorem_goal_ids = list(
            _runtime_row_string_values(row, "target_theorem_goal_ids")
        ) or list(target_ids)
        source_target_provenance = _source_theorem_target_provenance_from_row(row)
        diagnostics = {
            "candidate_id": candidate_id,
            "candidate_kind": str(row.get("candidate_kind", "") or ""),
            "source_field": str(row.get("source_field", "") or ""),
            "source_manifest_id": str(row.get("source_manifest_id", "") or ""),
            "source_manifest_path": source_manifest_path,
            "artifact_path": artifact_path,
            "kernel_check_artifact_path": str(
                row.get("kernel_check_artifact_path", "") or ""
            ),
            "proof_state_artifact_path": str(
                row.get("proof_state_artifact_path", "") or ""
            ),
            "target_lean_file": str(row.get("target_lean_file", "") or ""),
            "target_lean_line": int(row.get("target_lean_line", 0) or 0),
            "target_lean_column": int(row.get("target_lean_column", 0) or 0),
            "target_lean_declaration": str(
                row.get("target_lean_declaration", "") or ""
            ),
            "target_ids": list(target_ids),
            "target_theorem_goal_ids": list(target_theorem_goal_ids),
            "target_theorem_name": str(row.get("target_theorem_name", "") or ""),
            "source_theorem_target_provenance": source_target_provenance,
            "precheck_status": str(row.get("precheck_status", "") or ""),
            "precheck_errors": list(row.get("precheck_errors", []) or []),
            "local_lean_attempted": local_lean_attempted,
            "local_lean_compiled": local_lean_compiled,
            "local_lean_exit_status": str(row.get("local_lean_exit_status", "") or ""),
            "local_lean_project": str(row.get("local_lean_project", "") or ""),
            "local_lean_skipped_reason": str(
                row.get("local_lean_skipped_reason", "") or ""
            ),
            "local_lean_stdout_excerpt": str(
                row.get("local_lean_stdout_excerpt", "") or ""
            )[:500],
            "local_lean_stderr_excerpt": str(
                row.get("local_lean_stderr_excerpt", "") or ""
            )[:500],
            "source_theorem_target_known": row.get(
                "source_theorem_target_known",
                None,
            ),
            "diagnostic_helper_not_source_theorem": bool(
                row.get("diagnostic_helper_not_source_theorem", False)
            ),
            "lean_source_excerpt": str(row.get("lean_source_excerpt", "") or "")[:500],
            "memory_status": str(row.get("memory_status", "") or ""),
            "next_action": str(row.get("next_action", "") or ""),
            "proof_evidence_status": str(row.get("proof_evidence_status", "") or ""),
            "proof_evidence_boundary": str(
                row.get("proof_evidence_boundary", "") or ""
            )[:500],
        }
        repair_contract = _formalizer_local_lean_repair_contract_from_diagnostics(
            [diagnostics]
        )
        if repair_contract:
            diagnostics["local_lean_repair_contract"] = repair_contract
            diagnostics["local_lean_diagnostic_classes"] = list(
                repair_contract.get("diagnostic_classes", []) or []
            )
        feedback_rows.append(diagnostics)
    return tuple(feedback_rows)


